-- 3. Courses (63, staged as draft before child verification)
insert into public.courses (skill_id, slug, title, description, target_audience, outcomes, difficulty, estimated_duration_weeks, recommended_weekly_hours, recommended_schedule, prerequisites, thumbnail_url, author_name, completion_rules, publication_status, version, position)
select
  sk.id, v.slug, v.title, v.description, v.target_audience, v.outcomes, v.difficulty, v.estimated_duration_weeks, v.recommended_weekly_hours, v.recommended_schedule, v.prerequisites, v.thumbnail_url, v.author_name, v.completion_rules, v.publication_status, v.version, v.position
from (
  values
    ('frontend-development', 'frontend-development-foundations', 'Frontend Development Foundations', 'Master semantic HTML5, modern CSS layout systems, responsive design, modular JavaScript, DOM manipulation, form validation, and live static deployment.', 'Aspiring web developers, designers, and makers building responsive websites from scratch.', '["Write clean, accessible HTML5 documents with proper landmark and heading hierarchy","Build responsive multi-column interfaces using Flexbox, CSS Grid, and design tokens","Implement interactive DOM filtering, toggles, and validated forms in vanilla JavaScript","Audit and deploy a production-ready responsive business website to a live HTTPS URL"]'::jsonb, 'Beginner', 8, 5, '1 module (2 lessons + 1 practical exercise) per week', '["Basic comfort using a web browser and text editor"]'::jsonb, '', 'Kord Engineering Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('graphic-design', 'graphic-design-foundations', 'Graphic Design Foundations', 'Develop practical mastery in visual elements, colour theory, typography, grid composition, branding systems, digital tools, and print-ready production.', 'Beginners, content creators, and marketers creating crisp print and digital visuals.', '["Apply positive/negative space, scale contrast, and focal hierarchy deliberately","Build accessible 60-30-10 colour systems across RGB and CMYK workflows","Pair complementary typefaces with disciplined leading, tracking, and grid alignment","Produce and export a print-ready promotional flyer grounded in a coherent brand sheet"]'::jsonb, 'Beginner', 8, 4.5, '1 module (2 lessons + 1 studio exercise) per week', '["Access to any free or desktop design editor (Figma, Canva, Inkscape, or Affinity)"]'::jsonb, '', 'Kord Visual Design Studio', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('digital-marketing-fundamentals', 'digital-marketing-foundations', 'Digital Marketing Foundations', 'Learn full-funnel digital marketing from audience research, content pillars, social strategy, and conversion copywriting to campaign planning, analytics, and optimisation.', 'Beginners, founders, freelancers, and junior marketers planning structured growth campaigns.', '["Map customer journeys across Owned, Earned, and Paid channels cleanly","Conduct voice-of-customer audience research and write PAS/AIDA conversion copy","Plan a 7-day multi-channel campaign complete with standardised UTM attribution","Interpret CTR, CVR, CPA, and ROAS metrics to design disciplined A/B tests"]'::jsonb, 'Beginner', 8, 4.5, '1 module (2 lessons + 1 applied worksheet) per week', '["No prior marketing background required"]'::jsonb, '', 'Kord Growth & Marketing Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('public-speaking', 'communication-and-public-speaking', 'Communication and Public Speaking', 'Build clear everyday workplace communication and poised public speaking skills—covering active listening, vocal pacing, body language, persuasion, structure, delivery, and self-review.', 'Professionals, students, team leads, and founders preparing talks, pitches, and confident briefings.', '["Structure spoken talks and updates around audience priorities and the Rule of Three","Control vocal pacing, intentional anchor pauses, and grounded non-verbal presence","Weave Ethos, Pathos, and Logos ethically while handling Q&A calmly","Deliver, record, and critique a structured 2-minute presentation with reflection"]'::jsonb, 'Beginner', 8, 4, '1 module (2 lessons + 1 speaking drill) per week', '["No prior public speaking experience required"]'::jsonb, '', 'Kord Communication Lab', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('effective-communication', 'effective-communication-foundations', 'Effective Communication Foundations', 'Master message framing, audience awareness, active confirmation, and cross-channel clarity so spoken and written ideas produce shared understanding instead of costly rework.', 'Students, early-career professionals, and team contributors who want clear, confident daily communication.', '["Structure messages around audience context, desired decision, and concrete next steps","Eliminate ambiguity across spoken, synchronous, and asynchronous conversations","Confirm shared understanding using structured teach-back and recap habits","Adapt tone, detail depth, and channel selection to the stakes of the message"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('business-communication', 'business-communication-essentials', 'Business Communication Essentials', 'Communicate crisply across executive memos, status briefings, client escalations, and cross-departmental alignment using Bottom Line Up Front (BLUF) and commercial clarity.', 'Analysts, operators, coordinators, and aspiring managers presenting updates to leaders and clients.', '["Write decision-driven executive memos and briefing notes using BLUF structure","Translate operational metrics and risks into commercial trade-offs","Lead structured client and leadership status updates with poise","Standardize meeting proposals, escalation notes, and project handoffs"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('professional-communication', 'professional-workplace-communication', 'Professional Workplace Communication', 'Build composed, respectful communication habits across workplace channels—written etiquette, meeting readiness, boundary-setting, feedback reception, and cross-level professionalism.', 'New graduates, remote contributors, and career switchers building dependable workplace communication habits.', '["Maintain calm, respectful etiquette across email, Slack/Teams, and video calls","Receive critical feedback gracefully and convert notes into visible action","Communicate reliably with managers, peers, and senior stakeholders across levels","Resolve minor friction early before gossip or silent resentment takes hold"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('negotiation-skills', 'negotiation-skills-deal-craft', 'Negotiation Skills & Deal Craft', 'Prepare interests, BATNAs, anchors, multi-issue trade-offs, and durable written agreements for salary, vendor, client, and partnership negotiations.', 'Freelancers, account managers, job seekers, and operators negotiating rates, contracts, and terms.', '["Separate surface positions from underlying interests and calculate your BATNA/ZOPA","Set credible evidence-backed anchors without alienating partners","Build multi-variable packages that expand value instead of haggling purely on price","Handle hardball tactics and convert spoken agreements into crisp written terms"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('persuasion-and-influence', 'ethical-persuasion-stakeholder-influence', 'Ethical Persuasion & Stakeholder Influence', 'Earn genuine, ethical buy-in for ideas and initiatives by combining audience diagnostic empathy, credible proof, narrative framing, and coalition building.', 'Product leads, marketers, analysts, and change champions rallying alignment without formal authority.', '["Distinguish ethical persuasion anchored in mutual benefit from hollow manipulation","Map stakeholder incentives, fears, and decision criteria accurately","Weave data, concrete examples, and user stories into persuasive narratives","Build quiet pre-meeting coalitions so big proposals pass smoothly"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('active-listening', 'active-listening-diagnostic-inquiry', 'Active Listening & Diagnostic Inquiry', 'Listen past surface complaints using non-verbal presence, clean open-ended inquiry, reflective paraphrasing, and emotion labeling to uncover true root needs.', 'Coaches, customer researchers, managers, sales professionals, and peers seeking deeper alignment.', '["Recognize and silence common mental listening blocks such as premature problem-solving","Ask open, non-leading diagnostic questions that uncover unspoken constraints","Reflect content and underlying emotion accurately without robotic parroting","Hold constructive silence so speakers think aloud to clearer insight"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('conflict-resolution', 'workplace-conflict-resolution-mediation', 'Workplace Conflict Resolution & Mediation', 'Diagnose conflict roots early, de-escalate heated disputes calmly, mediate competing viewpoints neutrally, and co-create durable behavioral agreements.', 'Team leads, coordinators, project managers, and contributors navigating cross-team friction.', '["Separate task, process, and personal relationship conflicts cleanly","De-escalate defensive tension using neutral framing and cooling agreements","Facilitate structured 30-minute peer mediation sessions safely","Draft specific follow-up commitments that prevent recurring conflict loops"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('emotional-intelligence', 'emotional-intelligence-in-teams', 'Emotional Intelligence in Teams', 'Develop self-awareness, emotional regulation under stress, empathetic perspective-taking, and interpersonal composure to build high-trust collaborative teams.', 'Managers, team contributors, customer-facing leads, and emerging leaders navigating pressure.', '["Spot personal emotional triggers and insert calm choice gaps before reacting","Reframe unhelpful cognitive distortions under critique or ambiguity","Practice accurate perspective-taking without absorbing teammates'' burnout","Nurture psychological safety and steady morale across challenging cycles"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('leadership-and-teamwork', 'collaborative-leadership-teamwork', 'Collaborative Leadership & Teamwork', 'Align teams around clear shared outcomes, delegate effectively without micromanaging, strengthen peer reliability, and cultivate accountable team execution.', 'New team leads, project captains, student organizers, and cross-functional contributors.', '["Clarify team purpose, roles, and RACI decision rights cleanly upfront","Delegate meaningful ownership paired with clear support checkpoints","Run effective blameless retrospectives that improve shared workflow","Coach peer accountability without toxic micromanagement or drift"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('critical-thinking', 'structured-critical-thinking-reasoning', 'Structured Critical Thinking & Reasoning', 'Evaluate claims rigorously by isolating hidden assumptions, testing evidence quality, spotting logical fallacies and cognitive biases, and separating correlation from causation.', 'Analysts, decision-makers, writers, and students cutting through hype, spin, and flawed arguments.', '["Deconstruct complex claims into premises, hidden assumptions, and testable conclusions","Spot confirmation bias, survivorship bias, and common logical fallacies swiftly","Distinguish mere statistical correlation from credible causal mechanisms","Make sharper decisions using Steelmanning, base rates, and pre-mortem checks"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('problem-solving', 'root-cause-problem-solving', 'Root-Cause Problem Solving', 'Frame ambiguous problems accurately, diagnose underlying causes via Five Whys and Fishbone trees, generate diverse solutions, and validate experiments quickly.', 'Coordinators, analysts, support leads, and practitioners tackling recurring operational snags.', '["Write precise problem statements separating observable pain from premature blame","Trace recurring symptoms back to systemic root causes using 5 Whys and Issue Trees","Compare competing candidate fixes via impact-vs-effort prioritization matrices","Validate root fixes cleanly with small rapid tests and clear guardrail metrics"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('presentation-skills', 'slide-visual-presentation-skills', 'Slide & Visual Presentation Skills', 'Design uncluttered executive and educational presentations blending cohesive narrative arcs, insight-driven slide titles, clean visual hierarchy, and assured live delivery.', 'Analysts, designers, educators, and professionals presenting decks in meetings, pitches, and webinars.', '["Architect clean presentation storylines using SCQA before opening slide software","Replace crowded bullet walls with clear action headlines and focused visual anchors","Select effective charts and annotations that surface one insight instantaneously","Deliver decks smoothly across in-person rooms and remote screen shares without reading slides"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('networking-and-relationship-building', 'authentic-networking-relationship-building', 'Authentic Networking & Relationship Building', 'Cultivate genuine, reciprocal professional relationships through thoughtful outreach, generous value sharing, memorable conversations, and warm long-term follow-through.', 'Job seekers, freelancers, founders, and quiet professionals building real human networks without cringe.', '["Reframe networking cleanly around genuine curiosity and mutual generosity","Write concise respectful cold/warm outreach notes that earn high reply rates","Ask thoughtful informational conversation questions without awkwardly asking for jobs directly","Maintain light sustainable follow-up habits keeping dormant ties warm over years"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('general-writing', 'general-writing-foundations', 'General Writing Foundations', 'Build reliable sentence clarity, active syntax, paragraph cohesion, and clean revision habits so readers grasp your meaning on the very first pass.', 'Learners, students, and early-career professionals wanting crisp everyday prose across essays, notes, and articles.', '["Construct clear subject-verb-object sentences free of filler and tangled passive phrasing","Organize paragraphs around a single controlling idea with explicit logical transitions","Diagnose tone mismatches and eliminate vague modifiers during structured self-editing","Draft, revise, and proofread a 600-word explanatory piece to publication readiness"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('professional-writing', 'professional-writing-essentials', 'Professional Writing Essentials', 'Draft crisp internal memos, client updates, project proposals, SOPs, and delicate workplace notes that earn trust and accelerate team decisions.', 'Coordinators, analysts, consultants, and graduates transitioning into client-facing or cross-functional roles.', '["Select the optimal document format for memos, proposals, SOPs, and status briefs","Frame executive requests around scope, trade-offs, risk mitigation, and clear asks","Write empathetic yet firm client updates when delays or boundary adjustments occur","Standardize plain-English workplace procedures teammates follow without extra calls"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('business-writing', 'business-writing-bluf-mastery', 'Business Writing: BLUF & Decision Memos', 'Master Bottom Line Up Front (BLUF), Pyramid Principle storytelling, financial summary framing, and concise executive briefs built for high-stakes business leadership.', 'Managers, analysts, founders, and team leads presenting recommendations to leadership, boards, or partners.', '["Apply the Bottom Line Up Front (BLUF) standard across memos, briefs, and emails","Group complex data into logical MECE arguments using the Minto Pyramid Principle","Frame financial trade-offs, ROI timelines, and downside risks persuasively","Compress multi-page business analyses into sharp 1-page executive summaries"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('creative-writing', 'creative-writing-foundations', 'Creative Writing: Scene, Character & Narrative', 'Craft grounded scenes, memorable characters driven by specific desire, purposeful dialogue with subtext, and tight narrative pacing from opening hook to resolution.', 'Aspiring fiction writers, narrative creators, and storytellers looking to move beyond summary into vivid scenes.', '["Render sensory scenes showing character choices rather than abstract emotion labels","Design characters anchored by clear external goals, internal flaws, and pressure","Write natural dialogue carrying distinct voices, conflict, and unspoken subtext","Structure story arcs cleanly and trim passive exposition during self-revision"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('storytelling', 'storytelling-narrative-craft', 'Storytelling & Narrative Craft', 'Harness universal narrative arcs—ordinary world, stakes, tension, turning point, and transformation—for leadership talks, brand stories, journalism, and personal narratives.', 'Creators, educators, founders, and communicators turning dry facts and experiences into memorable human stories.', '["Spot raw human stakes and tension inside ordinary business or personal experiences","Structure applied stories cleanly using Hook-Struggle-Insight-Transformation arcs","Weave data points and customer voices seamlessly inside emotional narratives","Deliver concise 3-minute and 600-word stories built for recall and resonance"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('copywriting', 'copywriting-conversion-craft', 'Copywriting & Conversion Craft', 'Write customer-centered headlines, value propositions, landing pages, product copy, and ethical conversion CTAs grounded in real buyer voice rather than empty hype.', 'Marketers, founders, product writers, and freelancers crafting web pages, emails, and campaign copy that converts clearly.', '["Transform dry technical product features into concrete customer outcome benefits","Apply Voice-of-Customer (VoC) research cleanly to eliminate guesswork in headlines","Structure landing pages using PAS, AIDA, and Value-Objection-Proof sequences","Write high-clarity microcopy, CTAs, and A/B test variations rooted in testable hypotheses"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('technical-writing', 'technical-writing-documentation', 'Technical Writing & Product Documentation', 'Author developer docs, API references, quickstarts, and troubleshooting runbooks built on information architecture, exact prerequisites, and runnable examples.', 'Developers, product specialists, QA engineers, and aspiring technical writers building clear user and API documentation.', '["Separate Tutorials, How-To Guides, Explanations, and References using Diataxis architecture","Write quickstarts and procedural guides with exact environment prerequisites and failure checks","Document API endpoints, request parameters, error codes, and realistic copyable examples","Maintain docs-as-code workflows, consistent terminology glossaries, and low-drift docs"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('academic-writing', 'academic-writing-evidence-synthesis', 'Academic Writing & Evidence Synthesis', 'Formulate arguable scholarly theses, synthesize peer-reviewed sources cleanly without patchwriting, balance academic tone, and manage citations transparently.', 'University students, researchers, policy analysts, and graduate applicants producing rigorous papers and literature reviews.', '["Formulate focused, arguable research theses anchored in tension rather than broad summary","Synthesize multiple scholarly findings thematically instead of listing article-by-article summaries","Use disciplined paraphrasing, framing, and citation practices avoiding accidental plagiarism","Structure cohesive academic paragraphs (MEAL/TEEL), clear limitations, and nuanced hedges"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('report-writing', 'report-writing-analytical-briefs', 'Report Writing & Analytical Briefs', 'Turn operational logs, research audits, and project datasets into crisp executive reports featuring clear executive summaries, methodology notes, findings-vs-recommendations separation, and visual tables.', 'Analysts, coordinators, program managers, NGO leads, and consultants writing operational, research, or project evaluation reports.', '["Structure multi-section analytical reports with transparent Executive Summary, Methods, Findings, and Recommendations","Separate objective observed Findings strictly from judgment-based Recommendations","Design clear report tables, callout boxes, and numbered headings built for rapid scanning","Translate multi-week audits or incident reviews into crisp, impartial action briefs"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('email-writing', 'email-writing-workplace-outcomes', 'Email Writing for High-Trust Outcomes', 'Write crystal-clear workplace, client, and cold outreach emails featuring unmistakable subject lines, scannable formatting, diplomatic boundaries, and friction-free replies.', 'Professionals, freelancers, support coordinators, and students seeking faster replies and fewer misunderstandings across daily inboxes.', '["Write informative subject lines conveying topic, urgency, and required action in 7 words","Structure emails using the 3-Block Anatomy (Context -> Core Details -> Crisp Ask)","Handle delicate topics—late replies, rejections, escalations, and scheduling—gracefully","Use `To`, `CC`, `BCC`, threading, and sign-offs with crisp inbox etiquette"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('blogging', 'blogging-editorial-publishing', 'Blogging & Editorial Publishing', 'Plan reader-focused editorial calendars, write irresistible tutorial and opinion posts, format long-form web articles cleanly, and turn casual posts into compounding organic traffic.', 'Independent creators, company blog editors, niche educators, and founders building lasting audience trust through long-form articles.', '["Validate sustainable blog niches, audience pain clusters, and high-return post archetypes","Write engaging blog headlines, story-driven openings, and deep skimmable tutorials","Integrate visual callouts, real examples, and internal content hubs without filler fluff","Repurpose, update, and promote cornerstone articles sustainably post-publication"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('scriptwriting', 'scriptwriting-audio-video', 'Scriptwriting for Audio & Video', 'Write spoken scripts built for ears and eyes across YouTube explainers, podcasts, brand videos, and short-form reels—balancing tight spoken cadence, visual cues, and retention hooks.', 'Video creators, podcast producers, instructional designers, and brand storytellers scripting crisp, watchable content.', '["Write natural conversational syntax engineered to sound effortless aloud on camera or mic","Hook viewers visually and verbally within the critical first 5–15 seconds without clickbait","Format industry-clean Audio/Visual (A/V) two-column and narrative scripts with clear B-roll cues","Pace educational, commercial, and short-form scripts around attention resets and clear endings"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('content-strategy', 'content-strategy-editorial-systems', 'Content Strategy & Editorial Systems', 'Align business goals, audience journey stages, topical authority clusters, governance rules, and distribution operations into a sustainable content engine.', 'Content leads, marketers, product strategists, and solo operators building cohesive multi-channel publishing programs.', '["Audit existing content libraries using quantitative retention and qualitative gap matrices","Design topic-cluster and funnel-aligned editorial roadmaps tied cleanly to product goals","Establish lightweight editorial governance, style workflows, and briefing templates","Measure strategic impact via assisted conversions, retention, and organic compound lift"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('editing-and-proofreading', 'editing-proofreading-standards', 'Editing & Proofreading Standards', 'Master developmental structure editing, crisp line-editing rhythm, authoritative copyediting standards, and zero-slip mechanical proofreading without erasing the author’s natural voice.', 'Writers, editors, communications coordinators, QA reviewers, and freelancers responsible for publication-grade polish.', '["Separate the four editorial stages (Developmental, Line, Copyediting, Proofreading) in proper sequence","Tighten flabby prose, smooth rhythm, and eliminate redundancy while preserving author voice","Enforce uniform style sheets, grammar consistency, and factual cross-checks reliably","Execute cold-eye final proofreading routines catching elusive homophones, formatting, and layout slips"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('seo-writing', 'seo-writing-search-intent', 'SEO Writing & Search-Intent Architecture', 'Research search intent deeply, structure semantic headings and metadata naturally, write helpful E-E-A-T human-first guides, and optimize scannability cleanly without spammy keyword stuffing.', 'Content writers, bloggers, digital marketers, and solo founders growing durable organic search traffic ethically.', '["Classify exact search intent (Informational, Commercial, Transactional, Navigational) before outlining","Structure clean semantic headings (`H1–H3`), snippets, and internal topic links organically","Embed Experience, Expertise, Authoritativeness, and Trustworthiness (E-E-A-T) naturally into copy","Write irresistible organic meta titles, descriptions, and FAQ optimizations free of spam stuffing"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('entrepreneurship', 'entrepreneurship-foundations', 'Entrepreneurship: Problem Discovery & Lean Ventures', 'Validate urgent customer pains, design low-risk lean experiments, establish unit viability, and launch real small ventures sustainably before spending heavy capital.', 'Aspiring founders, side-project builders, and intrapreneurs launching new services or products from scratch.', '["Separate urgent, hair-on-fire customer problems from nice-to-have ideas","Run unbiased Mom-Test discovery interviews without pitching prematurely","Design smoke-test and concierge MVP experiments validating real willingness to pay","Establish simple Day-1 pricing, break-even cash math, and founding ethics"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('business-development', 'business-development-partnerships', 'Business Development & Strategic Partnerships', 'Identify high-leverage strategic partnerships, qualify enterprise & channel pipelines systematically, structure mutual co-marketing and distribution agreements, and convert relationships into durable revenue.', 'Partnerships leads, account growth specialists, founders, and B2B professionals expanding reach beyond solo cold selling.', '["Separate strategic Business Development (leverage/distribution) clearly from transactional sales","Map complementary ecosystem partners sharing your exact non-competing ideal buyer","Design win-win mutual partnership proposals with clean attribution and low partner friction","Run systematic BD pipeline cadences from cold partner warm-up through joint launch reviews"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('business-planning', 'business-planning-operating-models', 'Business Planning & Operating Models', 'Build clear, living operational business plans uniting strategy, realistic quarterly milestones, cash-flow assumptions, staffing capacity, and risk contingency playbooks—not dusty 50-page shelf documents.', 'Small business operators, department heads, entrepreneurs, and aspiring managers translating vision into quarterly execution.', '["Replace static fantasy 5-year fluff with concise living 12-month operating plans","Model revenue drivers, operating expense buckets, and hiring triggers transparently","Link high-level objectives cleanly to quarterly departmental OKRs and weekly scorecards","Design proactive Scenario A/B/C contingency plans ahead of market or cash disruptions"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('startup-fundamentals', 'startup-fundamentals-mvp-traction', 'Startup Fundamentals: Discovery, MVP & Early Traction', 'Move methodically from raw startup hypotheses through disciplined Build-Measure-Learn experiments, crisp MVP scoping, retention cohort health, and credible early traction signals.', 'First-time startup founders, product builders, and technical creators moving early concepts toward true Product-Market Fit.', '["Formulate explicit falsifiable startup hypotheses before building features","Scope lean landing-page, Wizard-of-Oz, and single-loop MVPs in days rather than quarters","Distinguish true retention cohorts from leaky vanity signups accurately","Navigate equity basics, co-founder alignment, and milestone readiness cleanly"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('business-model-development', 'business-model-development-economics', 'Business Model Development & Unit Economics', 'Architect viable value creation, delivery, and value-capture engines—matching pricing models, customer segments, channel economics, and LTV/CAC mechanics to build durable profitability.', 'Founders, strategy analysts, product managers, and operators designing or refining commercial revenue architectures.', '["Map all nine interdependent blocks of the Business Model Canvas cleanly with internal coherence","Compare subscription, usage, marketplace, freemium, and tiered service pricing engines rationally","Compute LTV, CAC, Payback Period, and Churn sensitivity to verify scalable economics","Innovate business models thoughtfully when margins compress or buyer habits evolve"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('market-research', 'market-research-customer-validation', 'Market Research & Customer Validation', 'Combine qualitative buyer interviews, unbiased survey architecture, credible TAM/SAM/SOM sizing, competitor win/loss dissection, and clean Jobs-to-be-Done insights into sharper strategic bets.', 'Product researchers, marketers, founders, and business analysts transforming raw customer noise into clear directional evidence.', '["Separate Qualitative \"Why\" discovery cleanly from Quantitative \"How Many\" validation","Write unbiased surveys avoiding leading traps, double-barreled prompts, and sampling distortion","Compute transparent Bottom-Up TAM/SAM/SOM market sizes cleanly grounded in real sources","Uncover authentic switching triggers using Jobs-to-be-Done (JTBD) and Competitor Win/Loss interviews"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('financial-literacy', 'financial-literacy-cashflow-margins', 'Financial Literacy: Cash Flow, Margins & Budgets', 'Read income statements, balance sheets, and cash-flow statements confidently—mastering gross vs. net margin, working capital timing, break-even pricing, and disciplined operational budgets.', 'Managers, small-business founders, creatives, and non-finance professionals making daily pricing and budget decisions.', '["Interpret the three core financial statements (P&L, Balance Sheet, Cash Flow) fluently","Calculate Gross Margin, Markup, Operating Margin, and Break-Even Volume without errors","Spot why fast-growing profitable companies run out of literal cash via Working Capital lag","Build 13-week rolling cash forecasts and variance budgets catching leaks early"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('small-business-management', 'small-business-management-operations', 'Small Business Management & Operations', 'Systematize daily small-business workflows—standardizing repeatable SOPs, managing supplier & inventory reliability, scheduling productive teams, and handling customer service smoothly without founder burnout.', 'Small business owners, shop/studio managers, operations coordinators, and clinic/agency supervisors.', '["Convert fragile founder memory into simple living checklists and visual SOP workflows","Balance inventory turnover, reorder points, and reliable backup vendor management","Lead respectful frontline team scheduling, daily shift huddles, and accountable coaching","Systematize customer service recovery, local reputation hygiene, and steady quality audits"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('sales-fundamentals', 'sales-fundamentals-consultative-closing', 'Sales Fundamentals & Consultative Discovery', 'Run high-trust consultative discovery calls, diagnose urgent pain and decision processes without pushy scripts, craft clear ROI proposals, resolve authentic objections calmly, and close clean ethical wins.', 'Account executives, SDRs, freelancers, consultants, and founders growing comfortable turning conversations into fair signed deals.', '["Replace pushy \"feature-dump monologues\" with structured Consultative Discovery diagnostics","Qualify Pain, Decision Power, Impact, and Compelling Event cleanly without interrogation","Frame compelling business proposals tied strictly to buyer-stated quantified costs","Handle pricing, timing, and status-quo objections calmly while maintaining clean Mutual Action Plans"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('customer-relationship-management', 'customer-relationship-management-retention', 'Customer Relationship Management & Retention', 'Design clean CRM lifecycle architectures, segment active customers cleanly by health signals, prevent silent churn proactively through automated milestones, and grow lasting net revenue retention.', 'Customer success specialists, account coordinators, small-business operators, and operations managers organizing client lifecycles.', '["Architect clean uncluttered CRM schemas (`Accounts, Contacts, Deals, Lifecycles`) teams actually maintain","Design proactive Health Scores catching quiet disengagement weeks ahead of cancellation","Orchestrate first-30-day onboarding milestones turning signups smoothly into loyal retained buyers","Structure ethical expansion, renewal alerts, and referral loops boosting Net Revenue Retention"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('branding', 'branding-positioning-identity', 'Branding, Positioning & Market Differentiation', 'Clarify unmistakable market positioning, craft differentiated brand promises, shape authentic verbal voice and identity rules, and steward consistent recognizable brand equity beyond logos alone.', 'Founders, marketers, designers, and independent creators turning forgettable commodity offers into trusted distinct brands.', '["Separate deep Strategic Positioning & Brand Equity cleanly from decorative logos and color palettes","Apply April Dunford’s Positioning logic (`Competitive Alternatives -> Unique Value -> Best-Fit Market`)","Codify crisp verbal Personality Guardrails (\"This, Not That\"), Narrative Pillars, and Taglines","Build living brand stewardship habits guarding distinctiveness consistently across customer journeys"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('product-management', 'product-management-specs-launches', 'Product Management: Discovery, Specs & Launches', 'Diagnose urgent user outcomes cleanly, resist building every loud feature request blindly, write crystal-clear Lean PRDs balancing engineering edge cases with scope, and lead cross-functional launches measured on real adoption.', 'Aspiring product managers, founders, engineers, and designers stepping into product ownership and roadmap decisions.', '["Separate Outcome-Driven Opportunity Discovery cleanly from blind Feature Factory request lists","Prioritize initiatives rationally using RICE, Opportunity Trees, and clear strategic trade-offs","Write concise 1–2 Page Lean PRDs clarifying user jobs, edge cases, non-goals, and analytics specs","Lead calm cross-functional Go-To-Market launches and measure genuine post-launch feature adoption"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('project-management', 'project-management-delivery', 'Project Management & On-Time Delivery', 'Scope ambiguous initiatives cleanly into Work Breakdown Structures, map realistic critical paths and risks early, run crisp standups and stakeholder check-ins, and close projects smoothly without last-minute panic.', 'Project coordinators, team leads, operations specialists, and independent delivery managers shipping cross-functional work.', '["Translate vague requests into crisp Project Charters (`Scope, Non-Goals, Owner, Deadline`) stopping scope creep early","Decompose big deliverables cleanly into Work Breakdown Structures (`WBS`) with realistic effort buffers","Spot critical-path bottlenecks, RAID risks, and cross-team handoff waits weeks before due dates","Lead calm status cadence, manage scope change requests cleanly, and run honest project retrospectives"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('strategic-thinking', 'strategic-thinking-decision-making', 'Strategic Thinking & Long-Term Planning', 'Diagnose root structural challenges cleanly instead of chasing noisy tactics, make sharp explicit trade-offs defining what NOT to pursue, anticipate second-order competitive moves, and align quarterly execution straight toward compounding advantage.', 'Managers, founders, operators, and emerging leaders transitioning from reactive daily execution into intentional multi-quarter direction.', '["Separate genuine **Strategy** (`diagnosis + coherent guiding choices + explicit trade-offs`) from fluffy wishlist goal lists","Trace **Second- and Third-Order Consequences** ahead of major pricing, hiring, or product pivots","Spot compounding **Competitive Moats & Leverage Points** rather than copying loud surface rival tactics","Translate multi-year strategic bets cleanly into crisp measurable quarterly Leading Signals (`Kill/Scale thresholds`)"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('business-negotiation', 'business-negotiation-dealmaking', 'Business Negotiation & Ethical Dealmaking', 'Walk into client rate talks, vendor contracts, partnership deals, and salary offers calmly prepared—uncovering shared underlying interests, leveraging crisp BATNA boundaries, trading asymmetric value creatively, and closing agreements that endure proudly.', 'Founders, account leads, freelancers, procurement coordinators, and managers negotiating contracts, scopes, vendors, and offers.', '["Prepare disciplined **BATNA, Reservation Price & Target Anchors** strictly ahead of every commercial meeting","Shift tense price tug-of-wars smoothly into **Interest-Based Multi-Variable Trades (`Price + Terms + Scope`)**","Deploy calm silence, calibrated open questions (`\"How am I supposed to do that?\"`), and principled anchoring gracefully","Spot bad-faith stall tactics calmly and finalize ironclad written summaries protecting both parties long-term"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('social-media-management', 'social-media-community-growth', 'Social Media, Community & Brand Growth', 'Plan sustainable 30-day social calendars, run high-trust Facebook & Meta Business pages, moderate healthy member communities, and build an authentic niche brand.', 'Social media coordinators, small business owners, creators, and community builders growing organic channels.', '["Build a repeatable 30-day content calendar balanced across education, proof, and community prompts","Optimize Facebook Business Pages and Meta Business Suite publishing, inbox routing, and trust signals","Moderate active online member spaces with clear norms, onboarding rituals, and advocate loops","Position an authentic niche personal brand anchored in documented craft rather than hype"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('facebook-and-instagram-advertising', 'paid-social-meta-ads-mastery', 'Paid Social & Meta Ads Campaign Mastery', 'Architect full-funnel Facebook and Instagram ad campaigns, structure clean Pixel/Conversions API signals, design creative testing matrices, and scale ROAS sustainably.', 'Marketers, founders, and freelancers running paid acquisition on Meta Ads Manager.', '["Select proper Meta campaign objectives (Sales, Leads, Awareness) instead of wasting money on Traffic clicks","Structure simplified Advantage+ and CBO/ABO account architectures that feed delivery algorithms cleanly","Diagnose CTR, CPM, Thumbstop Rate, Hold Rate, CPA, and Creative Fatigue before scaling spend","Configure clean UTM tracking, Pixel + CAPI deduplication concepts, and fair retargeting exclusions"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('google-ads', 'search-marketing-google-ads-sem', 'Search Marketing: SEO, Google Ads & SEM', 'Capture active buyer demand across organic Google Search and Google Ads—uniting technical/on-page SEO, tight ad group intent matching, negative keywords, and blended SEM ROI.', 'Digital marketers, web builders, and founders capturing high-intent search demand.', '["Map Search Intent (Informational, Commercial, Transactional) across SEO pages and Google Ads","Audit crawlability, semantic headings, Core Web Vitals basics, and topical internal linking cleanly","Structure high-Quality-Score Google Ads Search campaigns with Exact/Phrase match and Negative lists","Coordinate paid Search Ads with SEO rankings to lower blended Customer Acquisition Cost (CAC)"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('email-marketing', 'email-content-lead-generation', 'Email Lifecycle, Content, Influencers & Lead Gen', 'Build ethical lead magnets that attract qualified prospects, nurture subscribers with high-deliverability email sequences, publish trust-building content, and manage creator partnerships.', 'Growth marketers, creators, and small teams building sustainable owned acquisition engines.', '["Design high-intent lead magnets and low-friction capture forms qualifying leads naturally","Write segmented welcome, nurture, and re-engagement email flows respecting SPF/DKIM/DMARC deliverability","Operate a sustainable educational content marketing funnel tied directly to buyer stages","Scope, brief, and measure creator/influencer partnerships fairly using unique tracking codes and UTMs"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('marketing-analytics', 'marketing-analytics-cro-strategy', 'Marketing Analytics, CRO & Growth Strategy', 'Instrument accurate UTM & funnel analytics, calculate CAC/LTV/payback economics, run statistically sound A/B CRO experiments, and allocate cross-channel marketing strategy.', 'Growth analysts, performance marketers, product leads, and strategists driving measurable ROI.', '["Enforce standardized UTM taxonomy and distinguish Attribution limits cleanly","Compute unit economics accurately: CAC, LTV, Payback Period, Churn impact, and Blended MER","Diagnose landing-page conversion friction via qualitative + quantitative CRO audits and clean A/B tests","Synthesize positioning, budget allocation, and channel sequencing into resilient Marketing Strategy"]'::jsonb, 'Advanced', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('ui-ux-design', 'ui-ux-digital-product-design', 'UI/UX, Visual Thinking & Creative Systems', 'Practice structured creative ideation, map clear user flows and visual diagrams, design accessible responsive UI components, and run lightweight usability tests cleanly.', 'Aspiring product designers, web creators, and visual communicators building intuitive interfaces and information diagrams.', '["Apply divergent-to-convergent creative thinking frameworks to break stale first-idea ruts","Translate dense technical workflows into intuitive visual diagrams, charts, and user flows","Design accessible UI wireframes, interactive states (focus, error, empty), and responsive grids","Run unscripted 5-user usability tests uncovering real navigation snags prior to coding"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('brand-identity-design', 'canva-and-brand-identity-design', 'Brand Identity Systems, Canva & Art Direction', 'Architect memorable cohesive brand identities, execute fast repeatable brand kits and multi-format social templates cleanly inside Canva, and direct consistent visual campaigns across media.', 'Brand designers, small-business marketers, and creative leads producing recognizable multi-channel visual systems.', '["Build scalable brand identity toolkits (responsive marks, 60-30-10 color systems, voice-matched type)","Configure structured Canva Brand Kits, master grids, and reusable client-proof social templates","Establish cohesive Art Direction across photography styling, lighting mood, props, and composition","Package complete client-ready brand guideline manuals preventing messy off-brand drift"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('video-editing', 'photography-video-motion-production', 'Photography, Video Editing & Motion Storytelling', 'Master natural light photography composition, crisp rhythmic video editing with clean intelligible audio and captions, and restrained purposeful motion graphics that amplify stories.', 'Content creators, marketing generalists, and emerging visual producers working with phones, cameras, and modern editors.', '["Control exposure triangles, natural directional window light, and intentional framing cleanly","Edit engaging video stories using A-roll/B-roll pacing, L-cuts/J-cuts, clean voice audio, and readable captions","Animate crisp lower-thirds, kinetic callouts, and eased motion graphics honoring animation timing curves","Export sharp color-accurate photos and smooth multi-aspect (`16:9` / `9:16`) video deliverables reliably"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('web-development', 'web-development-and-git', 'Web Development, Git Version Control & Team Tools', 'Build semantic responsive websites, manage clean Git branching and pull requests, and coordinate team technical documentation and sprint boards cleanly.', 'Beginners entering software engineering, technical coordinators, and junior builders learning web standards alongside collaborative workflows.', '["Author semantic, accessible HTML5 pages styled with modern CSS Flexbox and Grid","Add clean client-side DOM validation and interactive state without brittle spaghetti scripts","Commit atomic Git changes, resolve merge conflicts, and review pull requests safely","Coordinate team specs, issue trackers, spreadsheets, and async engineering docs effectively"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('backend-development', 'backend-databases-full-stack', 'Backend APIs, Databases & Full-Stack Architecture', 'Design normalized relational PostgreSQL schemas, secure server-side APIs and RLS boundaries, parameterized queries, and cohesive end-to-end full-stack data flows.', 'Web builders progressing beyond static UIs into relational data modeling, server validation, authentication boundaries, and full-stack delivery.', '["Normalize relational tables with primary keys, foreign keys, check constraints, and targeted indexes","Write parameterized SQL queries and transactions avoiding N+1 loops and SQL injection","Design server-authoritative API routes and Row Level Security policies enforcing ownership","Connect frontend forms, optimistic/idempotent mutations, and backend persistence cleanly"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('mobile-app-development', 'mobile-apps-and-software-testing', 'Mobile App Development & Software Testing', 'Design resilient touch-first mobile application experiences with offline-tolerant sync, alongside deterministic unit, integration, and end-to-end software testing.', 'App builders crafting mobile interfaces and developers building reliable automated test suites that prevent production regressions.', '["Design thumb-friendly mobile navigation, 44px+ touch targets, and adaptive keyboard/safe-area layouts","Build resilient mobile network state handling with optimistic queues, caching, and retry backoff","Write clean Arrange-Act-Assert unit and integration tests using doubles without flaky timing traps","Design pragmatic QA test pyramids covering edge cases, offline failures, and regression suites"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('cybersecurity', 'cloud-devops-and-cybersecurity', 'Cloud Computing, DevOps, Security & Technical Support', 'Apply OWASP cybersecurity hardening, configure managed cloud storage and environments safely, automate CI/CD pipelines, and run structured incident triage and support.', 'Builders deploying live cloud applications who need practical security hygiene, reliable CI/CD delivery, and calm technical troubleshooting.', '["Identify and mitigate core OWASP risks including broken access control, injection, XSS, and secret leaks","Configure cloud compute, private storage buckets, MIME restrictions, and environment variable boundaries","Design repeatable CI/CD pipelines with preview checks, safe rollbacks, and health monitoring","Triage user technical incidents methodically with clear diagnostics and empathetic resolutions"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('data-analysis', 'data-analysis-ai-machine-learning', 'Data Analysis, Artificial Intelligence & Machine Learning', 'Clean and analyze datasets accurately with SQL and spreadsheets, apply AI tools critically with human verification, and understand supervised machine learning evaluation cleanly.', 'Analysts, builders, and curious professionals seeking rigorous quantitative thinking, responsible AI workflows, and core ML intuition without hype.', '["Audit messy datasets for duplicates, missing values, skewed averages, and sampling bias","Write clear grouping, aggregation, and cohort retention comparisons to answer real business questions","Design structured AI prompts with verification checks catching hallucinations and privacy leaks","Distinguish train/validation/test splits, overfitting, and precision/recall trade-offs in ML"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('cv-and-resume-writing', 'cv-interviews-and-portfolio', 'CVs, Interviews, Portfolios & Career Growth', 'Write impact-driven CVs, curate proof-first portfolio case studies, practice structured STAR interview stories, and build an intentional multi-quarter career roadmap.', 'Job seekers, career switchers, students, and freelancers turning real skills into credible interviews and offers.', '["Rewrite duty-list CVs into measurable achievement bullets tailored cleanly to real role specs","Curate 2–3 problem-process-outcome portfolio case studies proving hands-on capability","Deliver concise STAR interview stories and thoughtful questions for hiring managers","Map skill gaps, quarterly growth milestones, and sponsor/mentor feedback into a living career plan"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('remote-work-skills', 'remote-work-time-and-productivity', 'Remote Work, Professionalism, Time & Productivity', 'Thrive in distributed teams with crisp asynchronous communication, dependable workplace professionalism, realistic time-blocking, and sustainable personal productivity systems.', 'Remote professionals, hybrid workers, students, and builders looking to deliver calmly without constant meetings or burnout.', '["Write clear asynchronous updates, Loom walkthroughs, and written decisions reducing live meetings","Demonstrate rock-solid workplace reliability through early blocker alerts and graceful feedback handling","Apply time-blocking, energy-matched batching, and realistic weekly capacity limits","Maintain a trusted single capture-and-execution productivity system without endless to-do guilt"]'::jsonb, 'Beginner', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1),
    ('freelancing', 'freelancing-clients-and-personal-finance', 'Freelancing, Client Management, Networking & Personal Finance', 'Scope profitable freelance proposals, run calm client expectations without scope creep, build genuine referral networks, and manage irregular personal cash flow responsibly.', 'Freelancers, independent consultants, creators, and early professionals managing client relationships alongside personal financial stability.', '["Write clear milestone proposals specifying deliverables, revision limits, timelines, and payment terms","Handle scope creep, difficult client feedback, and weekly status check-ins calmly","Nurture authentic peer and referral networks without sleazy transactional pitching","Budget variable income, separate tax/operating reserves, and build personal emergency buffers"]'::jsonb, 'Intermediate', 4, 4, 'Complete 1–2 modules per week including guided activities and checkpoints.', '["No prior specialist certification required; willingness to complete practical exercises"]'::jsonb, '', 'Kord Curriculum Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'draft', 1, 1)
) as v(skill_slug, slug, title, description, target_audience, outcomes, difficulty, estimated_duration_weeks, recommended_weekly_hours, recommended_schedule, prerequisites, thumbnail_url, author_name, completion_rules, publication_status, version, position)
join public.skills sk on sk.slug = v.skill_slug
on conflict (slug) do update set
  skill_id = excluded.skill_id,
  title = excluded.title,
  description = excluded.description,
  target_audience = excluded.target_audience,
  outcomes = excluded.outcomes,
  difficulty = excluded.difficulty,
  estimated_duration_weeks = excluded.estimated_duration_weeks,
  recommended_weekly_hours = excluded.recommended_weekly_hours,
  recommended_schedule = excluded.recommended_schedule,
  prerequisites = excluded.prerequisites,
  thumbnail_url = excluded.thumbnail_url,
  author_name = excluded.author_name,
  completion_rules = excluded.completion_rules,
  publication_status = public.courses.publication_status,
  version = excluded.version,
  position = excluded.position,
  updated_at = now();

