-- 6. Phases / Modules (386)
insert into public.phases (id, course_id, skill_id, position, title, summary, objectives, difficulty, est_hours, publication_status)
select v.id::uuid, co.id, co.skill_id, v.position, v.title, v.summary, v.objectives, v.difficulty, v.est_hours, v.publication_status
from (
  values
    ('1452f148-671a-6af7-3d7d-91427b39afa1', 'frontend-development-foundations', 1, 'Introduction to Web Development', 'Understand how browsers, HTTP requests, HTML/CSS/JavaScript, and developer tools collaborate to render websites.', '["Explain the browser request-response cycle and separation of structure, presentation, and behaviour","Inspect live DOM trees and computed CSS styles using browser Developer Tools"]'::jsonb, 'Beginner', 2.5, 'published'),
    ('d038cf02-89ce-4d92-fa33-4a10e271793e', 'frontend-development-foundations', 2, 'HTML Fundamentals', 'Author semantic, accessible HTML5 documents with proper headings, landmarks, links, tables, and media attributes.', '["Structure full pages with semantic landmarks (<header>, <main>, <section>, <article>, <footer>)","Write descriptive alt text, ordered headings, and accessible interactive elements"]'::jsonb, 'Beginner', 3, 'published'),
    ('2d272456-d4a8-88d6-a92e-1eb58dcc0503', 'frontend-development-foundations', 3, 'CSS Fundamentals', 'Control selectors, specificity, cascade order, typography, CSS custom properties, and the CSS Box Model accurately.', '["Predict cascade and specificity winners without resorting to !important","Apply box-sizing: border-box, margin/padding rhythm, and design tokens via CSS variables"]'::jsonb, 'Beginner', 3.5, 'published'),
    ('1939f24b-98de-af0a-4beb-3217cfcdacba', 'frontend-development-foundations', 4, 'Layout and Responsive Design', 'Architect mobile-first Flexbox rows, CSS Grid multi-column layouts, fluid spacing, and responsive breakpoints.', '["Choose between Flexbox (1D alignment) and CSS Grid (2D layout tracks)","Build responsive multi-column grids using repeat(auto-fit, minmax(...)) and mobile-first media queries"]'::jsonb, 'Intermediate', 4, 'published'),
    ('420b4329-9c17-0c00-c0fd-c951a1cc859a', 'frontend-development-foundations', 5, 'JavaScript Fundamentals', 'Master variables, data types, functions, arrays, objects, conditionals, and immutable array transformations.', '["Write pure functions using const/let, arrow functions, and template literals","Transform arrays of objects cleanly with filter(), map(), find(), and reduce()"]'::jsonb, 'Intermediate', 4, 'published'),
    ('b5b3aedb-70a3-ad9b-f3cc-53d5e98b49e8', 'frontend-development-foundations', 6, 'DOM Manipulation', 'Select elements, attach event listeners, delegate dynamic click events, and update UI state safely without XSS.', '["Query DOM nodes and bind clean addEventListener handlers","Render dynamic lists safely using textContent or escaped templates instead of raw user HTML"]'::jsonb, 'Intermediate', 3.5, 'published'),
    ('fd887f97-0b99-8407-d9b7-28bc23d4f741', 'frontend-development-foundations', 7, 'Forms and Validation', 'Design accessible HTML forms with paired labels, native constraints, custom JS validation, and clear inline feedback.', '["Connect every <input>, <select>, and <textarea> to a visible <label for=\"...\">","Combine HTML5 constraints with friendly custom JavaScript error messages"]'::jsonb, 'Intermediate', 3, 'published'),
    ('d4e2b59d-c916-e976-6b79-4d636f308e48', 'frontend-development-foundations', 8, 'Website Integration and Deployment', 'Connect pages cleanly, optimise images and metadata, run pre-launch QA audits, and deploy a live static site.', '["Configure SEO title/meta tags, favicons, and clean relative internal links","Audit performance, responsiveness, and accessibility before deploying to static hosting"]'::jsonb, 'Intermediate', 3.5, 'published'),
    ('31078ffa-e680-0e73-5784-4bc0204f658f', 'graphic-design-foundations', 1, 'Introduction to Graphic Design', 'Understand graphic design as structured visual problem-solving across print, editorial, branding, and digital media.', '["Differentiate artistic expression from goal-driven visual communication","Deconstruct a creative brief into audience, message, and format constraints"]'::jsonb, 'Beginner', 2.5, 'published'),
    ('5cb69c74-cde2-63c7-9eff-99d475b442fe', 'graphic-design-foundations', 2, 'Elements of Design', 'Master line, shape, form, texture, space, and scale contrast to direct the viewer’s eye intentionally.', '["Use positive and negative space actively rather than crowding corners","Combine geometric and organic shapes with deliberate scale contrast"]'::jsonb, 'Beginner', 3, 'published'),
    ('72747bc7-f08d-7150-456f-63ed8621c540', 'graphic-design-foundations', 3, 'Colour Theory', 'Apply hue, saturation, value, colour harmonies, 60-30-10 ratios, and accessible contrast in RGB and CMYK.', '["Build disciplined 60-30-10 colour systems (canvas, structure, focal accent)","Distinguish RGB screen colour from CMYK ink colour and verify WCAG text legibility"]'::jsonb, 'Beginner', 3, 'published'),
    ('a536bd2d-4629-4ffd-e289-1fb96a3701db', 'graphic-design-foundations', 4, 'Typography', 'Select complementary typeface pairings, build clear modular type scales, and control tracking, leading, and alignment.', '["Pair at most two complementary font families (Display + Body)","Set readable line-height (leading), letter-spacing (tracking), and left-aligned rags"]'::jsonb, 'Beginner', 3.5, 'published'),
    ('649489f2-ad65-af24-188f-a3aa20b13aa2', 'graphic-design-foundations', 5, 'Layout and Composition', 'Construct Swiss grid columns, visual hierarchy paths, balanced alignments, and clean page proportions.', '["Use modular column grids and consistent margin gutters","Guide eye flow intentionally using Z-pattern or F-pattern focal anchors"]'::jsonb, 'Intermediate', 3.5, 'published'),
    ('01eaf2c3-097d-3b9f-0c1d-97df91122f34', 'graphic-design-foundations', 6, 'Branding Fundamentals', 'Connect brand positioning, tone, logo lockups, and mini style guides across customer touchpoints.', '["Articulate brand personality traits before sketching marks","Assemble a cohesive mini brand kit (logo safe space, palette, typography)"]'::jsonb, 'Intermediate', 3, 'published'),
    ('d1af902a-0525-a077-325b-48ae16152342', 'graphic-design-foundations', 7, 'Digital Design Tools', 'Work cleanly with vector shapes vs raster pixels, layers, reusable styles, and non-destructive editing workflows.', '["Choose vector graphics (SVG/PDF) for logos/type and high-res raster (PNG/JPG) for photos","Organise named layers, frames, and reusable colour/text styles"]'::jsonb, 'Intermediate', 3, 'published'),
    ('70274843-cdb0-65d3-eec9-1e9773769b27', 'graphic-design-foundations', 8, 'Professional Design Production', 'Prepare print-ready files (bleed, trim marks, safe zones), export crisp digital assets, and write client-ready design rationales.', '["Set 3mm bleed, trim safety margins, and outline/embed fonts properly","Export both print PDF and high-res digital PNG/WebP variants cleanly"]'::jsonb, 'Intermediate', 3.5, 'published'),
    ('6ee2ae2b-51e5-30da-6985-df81dcd26c65', 'digital-marketing-foundations', 1, 'Introduction to Digital Marketing', 'Connect customer acquisition, conversion funnels, owned/earned/paid channels, and clear commercial objectives.', '["Map Awareness, Consideration, Conversion, and Retention funnel stages","Distinguish Owned, Earned, and Paid digital media channels"]'::jsonb, 'Beginner', 2.5, 'published'),
    ('4fbbb134-2d0a-2a8f-0cd3-2e5d2da2f1ac', 'digital-marketing-foundations', 2, 'Audience Research', 'Move beyond vague demographics by documenting buyer pain points, triggers, objections, and search intent.', '["Conduct lightweight voice-of-customer research from reviews and interviews","Build an actionable Ideal Customer Profile (ICP) grounded in real quotes"]'::jsonb, 'Beginner', 3, 'published'),
    ('eef6d687-2e34-9aa3-e674-dc02fe223505', 'digital-marketing-foundations', 3, 'Content Marketing', 'Plan educational content pillars, repurpose flagship guides into micro-assets, and build organic trust.', '["Define 3–4 repeatable content pillars tied to buyer questions","Repurpose one deep piece into short articles, carousels, and emails"]'::jsonb, 'Beginner', 3, 'published'),
    ('8927aa09-f63d-ace2-96c4-a60f0deee13b', 'digital-marketing-foundations', 4, 'Social Media Marketing', 'Select the right social channels, structure balanced weekly cadences, spark genuine engagement, and format native posts.', '["Choose 1–2 primary platforms matched to audience habits instead of posting everywhere","Balance reach, trust-building, and conversion posts across a week"]'::jsonb, 'Beginner', 3, 'published'),
    ('5f2f372b-dd2c-ac45-c4dc-55da52b3fdc4', 'digital-marketing-foundations', 5, 'Copywriting', 'Write persuasive, clear headlines, PAS/AIDA frameworks, specific benefits, and friction-free calls-to-action.', '["Translate technical product features into concrete customer outcomes","Structure landing sections and emails using Problem–Agitate–Solve (PAS) and AIDA"]'::jsonb, 'Intermediate', 3.5, 'published'),
    ('114e11c2-a54b-c081-a03a-cb36e2526054', 'digital-marketing-foundations', 6, 'Campaign Planning', 'Coordinate multi-day launches combining editorial calendars, email sequences, paid touchpoints, and UTM tracking.', '["Design a cohesive 7-day launch calendar across complementary channels","Tag every campaign link cleanly with UTM parameters"]'::jsonb, 'Intermediate', 3.5, 'published'),
    ('9f52fbd6-9d99-0385-cee9-e5387e33ec33', 'digital-marketing-foundations', 7, 'Digital Marketing Analytics', 'Separate vanity metrics from actionable KPIs—CTR, Conversion Rate, CPA, CAC, ROAS, and cohort retention.', '["Calculate CTR, Conversion Rate, CPA, and ROAS accurately","Diagnose where a campaign funnel is leaking before changing ads blindly"]'::jsonb, 'Intermediate', 3.5, 'published'),
    ('9fb320ae-27f3-b05e-789b-a184bc9e631a', 'digital-marketing-foundations', 8, 'Campaign Optimisation', 'Run disciplined single-variable A/B tests, catch creative fatigue, and iterate campaigns systematically.', '["Formulate testable hypotheses (Change X -> Improve Y -> Because Z)","Avoid ending A/B tests prematurely on tiny sample sizes"]'::jsonb, 'Intermediate', 3, 'published'),
    ('a37791dc-3d3a-9c1a-2ea0-d13fe9246459', 'communication-and-public-speaking', 1, 'Communication Fundamentals', 'Master the sender-message-receiver loop, reduce signal noise, and establish mutual understanding before speaking at length.', '["Identify physical, semantic, and emotional communication noise","Frame clear messages around shared purpose and listener needs"]'::jsonb, 'Beginner', 2.5, 'published'),
    ('de26ab8c-a851-617c-5422-c354be6c14a7', 'communication-and-public-speaking', 2, 'Effective Verbal Communication', 'Sharpen vocal clarity, deliberate pacing, intentional pauses, plain language, and filler-word reduction.', '["Use 1-second silent pauses instead of \"um\" and \"like\" fillers","Vary pitch, volume, and pacing to highlight key takeaways"]'::jsonb, 'Beginner', 3, 'published'),
    ('ee983d8d-2805-6161-6ecf-c65338897282', 'communication-and-public-speaking', 3, 'Non-verbal Communication', 'Align posture, grounded stance, open hand gestures, eye contact, and camera framing with your spoken message.', '["Eliminate swaying and distracting nervous hand habits","Practise steady eye-contact zones in both live rooms and webcam calls"]'::jsonb, 'Beginner', 2.5, 'published'),
    ('667f0407-11a9-0e7c-1d61-dc368efd2f01', 'communication-and-public-speaking', 4, 'Audience Analysis', 'Tailor depth, vocabulary, examples, and emotional framing to executive, technical, community, or client audiences.', '["Map audience knowledge level, primary concerns, and decision authority","Adapt one core topic cleanly for two starkly different audiences"]'::jsonb, 'Beginner', 3, 'published'),
    ('0094ebe1-50a1-eb7f-a60d-a31d7cf80bbb', 'communication-and-public-speaking', 5, 'Presentation Structure', 'Architect talks using Rule of Three, strong opening hooks, logical signposts, and memorable conclusions.', '["Open without awkward throat-clearing (\"Um, hi everyone, so today...\")","Organise talks cleanly into Hook -> 3 Supporting Points -> Memorable Close"]'::jsonb, 'Intermediate', 3.5, 'published'),
    ('093c960b-d447-0ba6-c2ef-5cf102b861cb', 'communication-and-public-speaking', 6, 'Persuasive Communication', 'Balance Ethos, Pathos, and Logos ethically, handle tough objections calmly, and pair stories with hard evidence.', '["Combine credibility (Ethos), human stakes (Pathos), and logic/data (Logos)","Respond constructively to sceptical questions using Acknowledge–Bridge–Evidence"]'::jsonb, 'Intermediate', 3.5, 'published'),
    ('5b22e202-5186-acaa-dd56-23c790c35cf6', 'communication-and-public-speaking', 7, 'Presentation Delivery', 'Manage stage nerves physiologically, rehearse with timed cue cards rather than rote scripts, and recover smoothly.', '["Use box breathing and physical grounding prior to stepping on stage","Rehearse aloud against a strict 2-minute stopwatch using keyword cue cards"]'::jsonb, 'Intermediate', 3, 'published'),
    ('150dc5cb-6006-190d-a257-5f17784ef5bb', 'communication-and-public-speaking', 8, 'Feedback and Improvement', 'Conduct structured self-reviews across audio, visuals, and content, give constructive peer critiques, and iterate rapidly.', '["Audit a recorded talk separately for Audio-only, Video-muted, and Content flow","Turn raw critique into specific rehearsal adjustments"]'::jsonb, 'Intermediate', 3, 'published'),
    ('23219617-9d0a-35fa-1fab-6b7a1a0bb240', 'effective-communication-foundations', 1, 'Module 1: Clarity Mechanics & Audience Mapping', 'Diagnose why well-intended messages fail and structure every message around what the listener actually needs to act.', '["Identify common encoding and decoding noise","Profile audience constraints before speaking or writing"]'::jsonb, 'Beginner', 3, 'published'),
    ('28997796-7264-9fb2-23c9-55ab121828a0', 'effective-communication-foundations', 2, 'Module 2: Verbal Precision & Structured Speaking', 'Organize spontaneous and planned spoken contributions using crisp structural anchors.', '["Use PREP and What-So What-Now What structures in meetings","Manage pace, pauses, and vocal filler under pressure"]'::jsonb, 'Beginner', 3, 'published'),
    ('9cdea651-4911-9286-23e4-1a1a2af92e00', 'effective-communication-foundations', 3, 'Module 3: Channel Choice & Asynchronous Craft', 'Select the right medium—chat, email, doc, or live call—and write scannable async messages.', '["Match message urgency and complexity to the right channel","Design async updates that resolve questions in one pass"]'::jsonb, 'Beginner', 3, 'published'),
    ('912d563f-9943-1710-55b9-5bcd15d76884', 'effective-communication-foundations', 4, 'Module 4: Cross-Cultural & Empathetic Communication', 'Navigate differing communication styles, feedback norms, and unspoken cultural contexts respectfully.', '["Contrast high-context and low-context style preferences","Deliver candid feedback without triggering defensiveness"]'::jsonb, 'Beginner', 3, 'published'),
    ('1cc504bf-db16-8484-b404-38372f87db7b', 'effective-communication-foundations', 5, 'Module 5: Difficult Conversations & Alignment', 'Handle missed expectations, pushback, and tense trade-offs calmly and transparently.', '["Prepare balanced agendas for high-stakes conversations","De-escalate defensiveness and focus on shared constraints"]'::jsonb, 'Intermediate', 3, 'published'),
    ('9e7cc624-a318-9ddd-2e23-e383c443751b', 'effective-communication-foundations', 6, 'Module 6: Applied Communication Systems', 'Integrate active listening, written precision, and meeting facilitation into repeatable workplace habits.', '["Run concise decision meetings with clear agendas and notes","Audit personal communication habits across real projects"]'::jsonb, 'Intermediate', 3, 'published'),
    ('02956c56-6ae8-d670-4da0-39c5668b2b7e', 'business-communication-essentials', 1, 'Module 1: Executive Mindset & BLUF Structure', 'Reverse academic essay habits so busy decision-makers grasp recommendations within 15 seconds.', '["Apply the Pyramid Principle and BLUF to business memos","Separate recommendation, supporting pillars, and raw appendix"]'::jsonb, 'Beginner', 3, 'published'),
    ('6cb74937-974b-4df6-c819-3937aff785e4', 'business-communication-essentials', 2, 'Module 2: Commercial Storytelling & Data Reporting', 'Turn spreadsheets, metrics, and project milestones into meaningful business narratives.', '["Translate raw numbers into \"So What?\" insights","Write weekly RAG (Red/Amber/Green) status briefings honestly"]'::jsonb, 'Beginner', 3, 'published'),
    ('60aea828-d7e8-40e8-cfdc-2da13da4ad84', 'business-communication-essentials', 3, 'Module 3: Proposals, Business Cases & Briefs', 'Structure persuasive project proposals showing problem cost, solution scope, ROI, and risks.', '["Build a 1-page commercial business case","Anticipate finance and legal objections proactively"]'::jsonb, 'Beginner', 3, 'published'),
    ('224a23fb-baed-111f-17cc-d2e55e5b08c2', 'business-communication-essentials', 4, 'Module 4: Client & Cross-Department Communication', 'Manage external expectations, scope boundaries, and cross-functional handoffs gracefully.', '["Communicate confidently with clients and vendors","Write crisp handoff briefs between Sales, Delivery, and Support"]'::jsonb, 'Beginner', 3, 'published'),
    ('a917ceb5-0ffe-a06b-7f94-a8e993f988f9', 'business-communication-essentials', 5, 'Module 5: Crisis, Delay & Escalation Writing', 'Write transparent incident updates, executive escalations, and apology notes without spin.', '["Write fast, factual incident notifications","Structure escalations that invite swift decisions without politics"]'::jsonb, 'Intermediate', 3, 'published'),
    ('1c2a48b9-5bbe-513c-352d-bc8371c6b71f', 'business-communication-essentials', 6, 'Module 6: Business Writing System & Portfolio Pack', 'Audit grammar, executive tone, formatting consistency, and reusable workplace templates.', '["Apply consistent executive style checks before sending","Build reusable business memo, status, and escalation templates"]'::jsonb, 'Intermediate', 3, 'published'),
    ('e3ad5b01-1038-dce1-101f-8a95d823f484', 'professional-workplace-communication', 1, 'Module 1: Workplace Channel Etiquette & Tone', 'Read digital room norms accurately and write respectful, crisp workplace messages.', '["Format clean chat and email threads cleanly","Recognize subtle tone traps in fast messaging tools"]'::jsonb, 'Beginner', 3, 'published'),
    ('a105e90b-07d0-cd7f-4343-bd8ccde67c1b', 'professional-workplace-communication', 2, 'Module 2: Communicating Across Organizational Levels', 'Tailor conversations effectively for peers, direct managers, and skip-level leaders.', '["Manage up with clear status, options, and calendar awareness","Build peer credibility without overstepping authority"]'::jsonb, 'Beginner', 3, 'published'),
    ('2ed716cc-4d31-cb8e-9f88-ad025dea16f2', 'professional-workplace-communication', 3, 'Module 3: Receiving & Giving Feedback Professionally', 'Turn critique into career momentum and offer constructive peer input gracefully.', '["Listen openly to critical feedback without defensiveness","Ask clarifying questions and demonstrate visible follow-up"]'::jsonb, 'Beginner', 3, 'published'),
    ('e062b7bd-b3c5-5775-c1e4-228d712dcb2f', 'professional-workplace-communication', 4, 'Module 4: Meeting Professionalism & Video Presence', 'Show up prepared, contribute crisply, and maintain strong remote/in-person presence.', '["Contribute concisely without monopolizing or disappearing","Practice dependable remote audio, visual, and attention habits"]'::jsonb, 'Beginner', 3, 'published'),
    ('eb4454e1-1f11-a06a-fc80-24bc7178f3ee', 'professional-workplace-communication', 5, 'Module 5: Boundaries, Reliability & Accountability', 'Own mistakes transparently, protect focus hours, and keep promises across heavy weeks.', '["Take crisp ownership when errors happen","Communicate availability, handoffs, and boundaries clearly"]'::jsonb, 'Intermediate', 3, 'published'),
    ('28fedb46-1926-6e1b-faf4-d14cce6c628f', 'professional-workplace-communication', 6, 'Module 6: Workplace Professionalism Capstone Integration', 'Integrate written clarity, cross-level poise, accountability, and team etiquette in real workplace workflows.', '["Diagnose communication gaps in realistic workplace case scenarios","Articulate personal communication standards for interviews and teams"]'::jsonb, 'Intermediate', 3, 'published'),
    ('f5315b8e-656e-1cde-eb91-fea055de051f', 'negotiation-skills-deal-craft', 1, 'Module 1: Preparation, BATNA & Interests', 'Win 80% of negotiation outcomes before sitting at the table by mapping alternatives and true motives.', '["Calculate BATNA and reservation price objectively","Uncover partner interests behind rigid opening demands"]'::jsonb, 'Intermediate', 3, 'published'),
    ('5abbd9c6-14ad-970a-9ce5-0cdef4351703', 'negotiation-skills-deal-craft', 2, 'Module 2: Anchoring & Framing Opening Offers', 'Set credible opening anchors backed by objective benchmarks and manage counter-anchors smoothly.', '["Anchor confidently when you hold strong market data","Defuse aggressive lowball anchors cleanly"]'::jsonb, 'Intermediate', 3, 'published'),
    ('e38c7298-b863-964f-567e-a1e8b0a41deb', 'negotiation-skills-deal-craft', 3, 'Module 3: Multi-Issue Packaging & Creative Trades', 'Stop fighting over one number by bundling scope, terms, timelines, guarantees, and visibility.', '["Design Multi-Equivalent Simultaneous Offers (MESOs)","Trade low-cost/high-value concessions intentionally"]'::jsonb, 'Intermediate', 3, 'published'),
    ('d97f7db9-893e-d577-fb37-bf2acfbd1175', 'negotiation-skills-deal-craft', 4, 'Module 4: Difficult Tactics, Objections & Deadlocks', 'Stay calm when counterparts bluff, stall, nibble late, or cite "final budget authority".', '["Spot and neutralize common hardball tactics smoothly","Diagnose real deadlocks vs. genuine procedural constraints"]'::jsonb, 'Intermediate', 3, 'published'),
    ('b9fa1823-0666-6c6b-f3e8-b5a716a8ce1d', 'negotiation-skills-deal-craft', 5, 'Module 5: Salary, Contract & Stakeholder Negotiations', 'Apply negotiation craft directly to job offers, freelance proposals, and internal resource bids.', '["Negotiate total compensation holistically beyond base salary","Align internal stakeholders competing for shared budget or engineers"]'::jsonb, 'Intermediate', 3, 'published'),
    ('e74fd32c-a957-b765-5baf-1aeff7e84359', 'negotiation-skills-deal-craft', 6, 'Module 6: Closing Agreements & Long-Term Trust', 'Convert handshake agreements into clean written records and evaluate negotiation performance.', '["Draft crisp deal summary emails locking scope, price, and timelines","Conduct post-negotiation audits to refine future craft"]'::jsonb, 'Intermediate', 3, 'published'),
    ('e40ccf59-0506-c18d-3b52-25c5da52a409', 'ethical-persuasion-stakeholder-influence', 1, 'Module 1: Ethical Influence & Decision Psychology', 'Understand how busy humans weigh evidence, risk, and social trust before backing change.', '["Apply Cialdini/Aristotle ethical persuasion pillars transparently","Diagnose loss aversion blocking otherwise sound ideas"]'::jsonb, 'Intermediate', 3, 'published'),
    ('fe06067e-1c0e-1c1d-7ad1-f7e89b62e2cf', 'ethical-persuasion-stakeholder-influence', 2, 'Module 2: Storytelling With Evidence & Framing', 'Shape concrete case evidence and numbers into clear, memorable arguments.', '["Use contrast and \"One Customer\" anchors alongside statistics","Frame proposals around each listener''s highest goal"]'::jsonb, 'Intermediate', 3, 'published'),
    ('5305a08f-7cc3-b754-0303-dc73a83463fc', 'ethical-persuasion-stakeholder-influence', 3, 'Module 3: Influence Without Formal Authority', 'Rally peers and cross-functional teams when you cannot simply issue mandates.', '["Build social proof and quiet coalition alignment","Run pre-meeting 1:1 previews before big pitch rooms"]'::jsonb, 'Intermediate', 3, 'published'),
    ('801f9f19-bd6e-b918-43b7-75bbccb9baed', 'ethical-persuasion-stakeholder-influence', 4, 'Module 4: Handling Skepticism & Persuasive Q&A', 'Stay poised under sharp questioning, turn doubts into dialogue, and concede gracefully when wrong.', '["Use Feel-Felt-Found and curious inquiry with tough skeptics","Know when to adapt or drop weak parts of your proposal"]'::jsonb, 'Intermediate', 3, 'published'),
    ('6ceeff26-f5e5-a158-9a75-c3b52ce4e77c', 'ethical-persuasion-stakeholder-influence', 5, 'Module 5: Driving Behavioral Adoption & Change', 'Ensure persuasive agreements survive beyond applause into actual team behavior change.', '["Design friction-free defaults and launch reminders","Measure post-buy-in adoption honestly"]'::jsonb, 'Intermediate', 3, 'published'),
    ('b56af6ea-350e-518b-279a-81eb4acfa578', 'ethical-persuasion-stakeholder-influence', 6, 'Module 6: Ethical Persuasion Campaign Capstone', 'Combine stakeholder analysis, evidence storytelling, coalition pre-wiring, and objection Q&A into one complete pitch.', '["Synthesize narrative, evidence, and ethical guardrails","Defend change proposals cleanly before skeptical decision-makers"]'::jsonb, 'Intermediate', 3, 'published'),
    ('cf2ce472-e39a-e78f-d81f-d546a2a92bc3', 'active-listening-diagnostic-inquiry', 1, 'Module 1: Breaking Everyday Listening Barriers', 'Notice how rehearsing replies, fixing too fast, and judging prematurely block genuine understanding.', '["Identify the five common listening derailers","Shift attention cleanly from self-rehearsal to speaker presence"]'::jsonb, 'Beginner', 3, 'published'),
    ('672c6349-ffcf-df7a-5763-3c5c366f1a22', 'active-listening-diagnostic-inquiry', 2, 'Module 2: Clean Open Inquiry & Precision Questions', 'Replace leading or yes/no interrogations with clear open questions that invite deep thinking.', '["Use \"What\" and \"How\" questions instead of leading yes/no traps","Practice funnel questioning from broad context down to specifics"]'::jsonb, 'Beginner', 3, 'published'),
    ('082750d2-444f-8046-9146-3a8fdf35a1b9', 'active-listening-diagnostic-inquiry', 3, 'Module 3: Reflective Paraphrasing & Emotion Labeling', 'Mirror meaning and unstated feelings accurately without sounding mechanical or robotic.', '["Distinguish genuine paraphrasing from literal word-for-word repeating","Label speaker emotions gently to defuse stress"]'::jsonb, 'Beginner', 3, 'published'),
    ('a1c4dbde-d79c-6101-bf97-f55b4b642600', 'active-listening-diagnostic-inquiry', 4, 'Module 4: Listening to Non-Verbal Signals & Silence', 'Read body cues responsibly without over-interpreting and master comfortable, productive silence.', '["Interpret non-verbal clusters cautiously alongside spoken words","Hold three-to-five-second silences for deeper speaker reflection"]'::jsonb, 'Beginner', 3, 'published'),
    ('72bfa1ac-755a-5ae4-458e-53cf573cfe65', 'active-listening-diagnostic-inquiry', 5, 'Module 5: Active Listening in High-Friction Settings', 'Apply deep listening during angry customer calls, tense 1:1s, and multi-party group debates.', '["Keep steady focus while receiving personal heat or complaints","Summarize competing multi-speaker views cleanly"]'::jsonb, 'Intermediate', 3, 'published'),
    ('26309203-9ee8-2448-88a8-1ba6c7602e78', 'active-listening-diagnostic-inquiry', 6, 'Module 6: Building an Active Listening Culture', 'Integrate diagnostic inquiry and reflective listening into leadership, research, and daily work.', '["Run effective user interviews, coaching chats, and listening check-ins","Audit personal listening growth with objective feedback"]'::jsonb, 'Intermediate', 3, 'published'),
    ('387f631e-ebe9-b7c9-b57d-75f1f92591c7', 'workplace-conflict-resolution-mediation', 1, 'Module 1: Anatomy of Workplace Conflict', 'Identify whether friction stems from unclear process, competing KPIs, scarce resources, or personal style clashes.', '["Distinguish task debate from destructive personal friction","Spot early conflict warning signs before escalation"]'::jsonb, 'Intermediate', 3, 'published'),
    ('2920d477-7a3a-8b17-be37-3308d9aa784b', 'workplace-conflict-resolution-mediation', 2, 'Module 2: De-Escalation & Ground Rules', 'Cool emotional spikes safely and establish constructive norms before resolving substance.', '["Use grounding language to restore calm dialogue","Reset spiraling conversations with explicit time-outs safely"]'::jsonb, 'Intermediate', 3, 'published'),
    ('41542d34-46ef-8293-5f3f-e162ab2bd3ff', 'workplace-conflict-resolution-mediation', 3, 'Module 3: Structured Peer Mediation', 'Run a balanced step-by-step mediation session helping two conflicted colleagues resolve issues fairly.', '["Maintain scrupulous facilitator neutrality","Guide parties smoothly through story sharing to option building"]'::jsonb, 'Intermediate', 3, 'published'),
    ('cdd09ece-450a-5be5-569b-12df4dcead12', 'workplace-conflict-resolution-mediation', 4, 'Module 4: Cross-Cultural, Power & Remote Conflicts', 'Navigate hierarchy dynamics, remote text misunderstandings, and differing norms sensitively.', '["Resolve remote Slack/email conflicts fast via voice bridges","Address power imbalances ethically during disagreements"]'::jsonb, 'Intermediate', 3, 'published'),
    ('ecd03324-7762-1c7f-bfc3-d43852e6e7f4', 'workplace-conflict-resolution-mediation', 5, 'Module 5: Behavioral Agreements & Follow-Through', 'Ensure peace agreements hold Tuesday morning through explicit rules and 14-day check-ins.', '["Turn vague \"let''s respect each other\" vows into measurable habits","Schedule short follow-up checks to verify healed trust"]'::jsonb, 'Intermediate', 3, 'published'),
    ('869bc319-eddd-ee92-5fed-312ef0a984e8', 'workplace-conflict-resolution-mediation', 6, 'Module 6: Conflict Resolution Mastery Capstone', 'Integrate diagnosis, de-escalation, neutral mediation, and behavioral charters cleanly.', '["Navigate complex multi-party conflicts systematically","Foster psychologically safe disagreement culture"]'::jsonb, 'Intermediate', 3, 'published'),
    ('c836c408-5a67-92d0-4d56-40fabbcfe17c', 'emotional-intelligence-in-teams', 1, 'Module 1: Self-Awareness & Trigger Mapping', 'Track real emotional patterns daily so blind stress reactions stop hijacking your judgment.', '["Build granular emotional vocabulary beyond \"fine\" or \"mad\"","Map recurring workplace triggers cleanly"]'::jsonb, 'Beginner', 3, 'published'),
    ('be4992cf-ad8d-1471-f075-6a6df53f1831', 'emotional-intelligence-in-teams', 2, 'Module 2: Self-Regulation & Composure Under Fire', 'Reclaim clear prefrontal focus during unexpected setbacks, harsh reviews, or shifting deadlines.', '["Use physiological reset and cognitive reframing rapidly","Prevent emotional contagion across teams during crises"]'::jsonb, 'Beginner', 3, 'published'),
    ('8193ca48-e4ac-016b-c3fa-7ad7dd47ed62', 'emotional-intelligence-in-teams', 3, 'Module 3: Empathy Without Burnout', 'Read others'' true perspectives deeply while keeping healthy emotional boundaries intact.', '["Contrast cognitive empathy, emotional care, and compassionate action","Prevent empathy fatigue among helping or support roles"]'::jsonb, 'Beginner', 3, 'published'),
    ('84037b1e-0496-ff66-75f0-8b72d90f11ab', 'emotional-intelligence-in-teams', 4, 'Module 4: Motivation, Resilience & Growth Mindset', 'Recover quickly from rejection, steady intrinsic motivation, and foster resilient team energy.', '["Treat setbacks as diagnostic data rather than permanent verdicts","Connect daily tasks back to meaningful user impact"]'::jsonb, 'Beginner', 3, 'published'),
    ('fc00135e-f078-5521-8df0-293e7904b50e', 'emotional-intelligence-in-teams', 5, 'Module 5: Social Intelligence & Team Trust', 'Read group dynamics accurately, build inclusive space, and elevate collective EQ.', '["Notice excluded voices and subtle status dynamics in rooms","Foster high psychological safety within peer circles"]'::jsonb, 'Intermediate', 3, 'published'),
    ('4af2c88f-6956-14a4-37d6-0e22873d7e37', 'emotional-intelligence-in-teams', 6, 'Module 6: Sustained High-EQ Leadership', 'Integrate self-regulation, empathy, resilience, and relational safety into daily life.', '["Synthesize a personal EQ operating standard","Coach peers toward calmer emotional agility"]'::jsonb, 'Intermediate', 3, 'published'),
    ('13845ab2-ef34-8621-32f9-0f4e867076a1', 'collaborative-leadership-teamwork', 1, 'Module 1: Clarity of Purpose & Role Alignment', 'Prevent overlapping effort and dropped handoffs by establishing shared mission and clear ownership.', '["Draft concise team charters and RACI ownership matrices","Establish healthy team communication norms day one"]'::jsonb, 'Intermediate', 3, 'published'),
    ('526e5cad-3892-e9a0-9ec6-a3e8ad2e1a0d', 'collaborative-leadership-teamwork', 2, 'Module 2: Effective Delegation & Autonomy', 'Multiply team capacity by handing over meaningful outcomes matched to clean guardrails.', '["Delegate outcomes with clear autonomy levels instead of hovering","Tailor check-in support to member readiness"]'::jsonb, 'Intermediate', 3, 'published'),
    ('7ecc875b-e75f-716e-d474-30abedb88409', 'collaborative-leadership-teamwork', 3, 'Module 3: Team Accountability & Peer Dependability', 'Follow through relentlessly on team commitments and address missed expectations early with care.', '["Distinguish genuine peer reliability from busy noise","Have calm accountability check-ins when commitments slip"]'::jsonb, 'Intermediate', 3, 'published'),
    ('4ee59275-10d0-fc17-36a9-075ea019355b', 'collaborative-leadership-teamwork', 4, 'Module 4: Collective Decision-Making & Synthesis', 'Avoid endless analysis paralysis and loud-voice groupthink using structured team decision habits.', '["Apply Type 1 (irreversible) vs. Type 2 (reversible) decision speed","Use silent pre-writes and structured voting to defeat groupthink"]'::jsonb, 'Intermediate', 3, 'published'),
    ('ee02c101-da40-e6a8-d35f-ce6bd3f65662', 'collaborative-leadership-teamwork', 5, 'Module 5: Feedback Cycles, Retrospectives & Conflict Care', 'Turn every sprint or milestone finish into genuine continuous improvement through blameless retrospectives.', '["Facilitate crisp 35-minute blameless retrospectives","Convert retro insights into 1–2 owned system tweaks next sprint"]'::jsonb, 'Intermediate', 3, 'published'),
    ('dae3abee-66d4-4942-e2fa-b35604807e0f', 'collaborative-leadership-teamwork', 6, 'Module 6: Team Leadership Integration & Growth', 'Integrate purpose alignment, empowering delegation, inclusive decisions, and steady accountability.', '["Diagnose team stage friction (Forming, Storming, Norming, Performing)","Lead peers cleanly with or without formal manager title"]'::jsonb, 'Intermediate', 3, 'published'),
    ('2bb52472-6863-e6a2-416f-3222e3444f34', 'structured-critical-thinking-reasoning', 1, 'Module 1: Deconstructing Arguments & Assumptions', 'Pull apart persuasive rhetoric cleanly into evidence premises, unspoken leaps, and actual conclusions.', '["Map claims into Premises + Warrant + Conclusion","Uncover dangerous hidden assumptions inside business cases"]'::jsonb, 'Intermediate', 3, 'published'),
    ('24d438f6-9a9a-151f-5d27-708c1d6417e2', 'structured-critical-thinking-reasoning', 2, 'Module 2: Cognitive Biases & Blind Spots', 'Catch confirmation bias, survivorship bias, anchoring, and sunk-cost traps in your own reasoning.', '["Diagnose top reasoning biases inside live reports","Implement debiasing habits like disconfirming evidence searches"]'::jsonb, 'Intermediate', 3, 'published'),
    ('63497e33-970b-b884-77ac-0dce7ee582de', 'structured-critical-thinking-reasoning', 3, 'Module 3: Fallacies, Spin & Evidence Evaluation', 'Recognize strawman tactics, false dilemmas, misleading averages, and correlation-causation errors cleanly.', '["Spot common logical fallacies instantly in articles and decks","Audit basic chart and percentage tricks accurately"]'::jsonb, 'Intermediate', 3, 'published'),
    ('c7125415-eae3-24aa-f8bd-6d3b549bea0c', 'structured-critical-thinking-reasoning', 4, 'Module 4: Probabilistic Thinking & Steelmanning', 'Think in base rates and scenarios cleanly, and sharpen positions through principled Steelmanning.', '["Apply base-rate awareness before forecasting bold outliers","Steelman opposing arguments fairly before picking final strategy"]'::jsonb, 'Intermediate', 3, 'published'),
    ('d64d3fec-bf94-43d3-4e59-ed8293d10000', 'structured-critical-thinking-reasoning', 5, 'Module 5: Pre-Mortems & High-Stakes Decision Craft', 'Anticipate catastrophic failure paths systematically before irreversible steps fire.', '["Run 20-minute team pre-mortems effectively","Compare options cleanly with weighted decision matrices"]'::jsonb, 'Intermediate', 3, 'published'),
    ('f925cb3f-0bad-a4bd-5b30-30155ba21d8d', 'structured-critical-thinking-reasoning', 6, 'Module 6: Critical Thinking Capstone Synthesis', 'Integrate assumption auditing, bias checks, causal evaluation, and decision matrices cleanly.', '["Audit unfamiliar claims systematically within minutes","Build daily habits resisting fast misinformation and hype"]'::jsonb, 'Intermediate', 3, 'published'),
    ('8dcdb9b3-e64a-b6ff-b701-ce37c5334c44', 'root-cause-problem-solving', 1, 'Module 1: Framing the Real Problem Cleanly', 'Avoid solving the wrong symptom brilliantly by writing clear scope-bound problem statements.', '["Distinguish symptoms, guessed solutions, and true baseline problems","Apply SCQA problem framing cleanly"]'::jsonb, 'Beginner', 3, 'published'),
    ('c6df54f0-df1a-bb05-6bca-1652a35264a9', 'root-cause-problem-solving', 2, 'Module 2: Root-Cause Analysis Tools', 'Dig beneath Band-Aid patches using structured Five Whys and Ishikawa Fishbone diagrams.', '["Conduct multi-branch 5 Whys cleanly without stopping at surface blame","Map People, Process, Tools, and Environment causes systematically"]'::jsonb, 'Beginner', 3, 'published'),
    ('548372aa-231f-8f06-6da0-d3c4bdefcce2', 'root-cause-problem-solving', 3, 'Module 3: Ideation & Solution Prioritization', 'Generate broader creative solutions beyond obvious first ideas and pick highest-leverage moves wisely.', '["Push past obvious quick hacks via structured ideation","Plot options cleanly onto Impact vs. Effort 2x2 grids"]'::jsonb, 'Beginner', 3, 'published'),
    ('f2f875a1-51a9-d831-2eaf-ae6eebe030e9', 'root-cause-problem-solving', 4, 'Module 4: Rapid Testing, Trade-Offs & Guardrail Metrics', 'Test candidate fixes cheaply before scaling broadly and watch for unintended side effects.', '["Design clean 7-day pilot tests with pre-set success metrics","Identify second-order unintended consequences proactively"]'::jsonb, 'Beginner', 3, 'published'),
    ('71558fbf-5689-3780-7402-faf5783e000a', 'root-cause-problem-solving', 5, 'Module 5: Handling Ambiguity & Messy Real-World Snags', 'Stay decisive and structured when data stays incomplete, urgent timelines crunch, and opinions clash.', '["Apply Hypothesis-Driven Troubleshooting fast under time crunch","Make progress cleanly with imperfect 70% information"]'::jsonb, 'Intermediate', 3, 'published'),
    ('4164cde9-a0b6-a426-68fb-43c39209ed63', 'root-cause-problem-solving', 6, 'Module 6: Problem-Solving Systems & Case Mastery', 'Institutionalize reusable troubleshooting runbooks and solve end-to-end ambiguous business snags.', '["Document clean one-page troubleshooting playbooks","Synthesize diagnosis, options, trade-offs, and validation into crisp briefs"]'::jsonb, 'Intermediate', 3, 'published'),
    ('b93557ce-ec85-1355-a460-0a60d65cb0d9', 'slide-visual-presentation-skills', 1, 'Module 1: Storylining Before Opening Slide Apps', 'Outline persuasive presentation narratives on paper first so decks avoid disconnected clutter.', '["Structure decks with Situation-Complication-Question-Answer (SCQA)","Write a horizontal storyboard of action headlines"]'::jsonb, 'Beginner', 3, 'published'),
    ('d5b0ba97-83b2-dcdb-e46b-3cb3bac58fd6', 'slide-visual-presentation-skills', 2, 'Module 2: Visual Hierarchy, Typography & Layout', 'Apply whitespace, contrast, alignment grids, and restrained typography so slides look calm and effortless.', '["Enforce clean 3-second visual readability rules","Replace bullet-point walls with simple spatial layouts"]'::jsonb, 'Beginner', 3, 'published'),
    ('9369485a-82c8-0439-f92c-243e40fbccaa', 'slide-visual-presentation-skills', 3, 'Module 3: Chart Craft & Data Storytelling', 'Pick right charts cleanly, declutter axis junk, and spotlight numbers with zero confusion.', '["Choose Bar, Line, or Callout formats accurately per data shape","Eliminate 3D pie distortion and noisy gridlines"]'::jsonb, 'Beginner', 3, 'published'),
    ('d5dc6d89-41a3-8095-c113-d6fd00e0a905', 'slide-visual-presentation-skills', 4, 'Module 4: Delivery, Slide-Voice Sync & Transitions', 'Present live slides fluidly without turning your back, reading sentences word-for-word, or stumbling transitions.', '["Use Assert-Then-Show click pacing cleanly","Bridge smoothly across slides in spoken transitions"]'::jsonb, 'Beginner', 3, 'published'),
    ('9a5573b0-7ab1-c35e-3b8e-f938f9d54d42', 'slide-visual-presentation-skills', 5, 'Module 5: Remote Webinars & Interactive Presentations', 'Keep remote video audiences engaged without fatigue using pacing resets, polls, and clean screen hygiene.', '["Build micro-engagement resets every 4–5 minutes remotely","Test audio, pointer tools, and remote screen safety smoothly"]'::jsonb, 'Intermediate', 3, 'published'),
    ('c8ea9117-73f1-81fe-f8f5-6ba7e3d2d6a8', 'slide-visual-presentation-skills', 6, 'Module 6: Presentation Mastery Capstone', 'Pull SCQA storyboarding, visual restraint, clear charts, and polished Q&A prep together completely.', '["Critique complete presentation decks objectively across narrative, visuals, and delivery","Rehearse smoothly using time-anchored timing checks"]'::jsonb, 'Intermediate', 3, 'published'),
    ('163fb307-5f78-658e-da7f-f6111b1aa30d', 'authentic-networking-relationship-building', 1, 'Module 1: Generous Networking Mindset & Audit', 'Replace transactional "collecting contacts" awkwardness with authentic human curiosity.', '["Audit current loose/dormant ties already in your orbit","Spot value-first ways early-career peers can help seniors authentically"]'::jsonb, 'Beginner', 3, 'published'),
    ('f55d21e2-a2c2-fbef-19bb-083ff199b69f', 'authentic-networking-relationship-building', 2, 'Module 2: Crisp Warm & Cold Outreach Writing', 'Craft short, respectful messages that earn answers from busy strangers and loose peers.', '["Apply the 5-Line Respectful Outreach Formula","Avoid vague \"Can I pick your brain?\" requests completely"]'::jsonb, 'Beginner', 3, 'published'),
    ('5f4039d5-239c-c90f-8235-3940288325b7', 'authentic-networking-relationship-building', 3, 'Module 3: Running High-Value Informational Conversations', 'Turn 15-minute coffee chats into remarkable learning exchanges leaving guests energized.', '["Prepare 3 targeted thoughtful questions respecting the 15-minute clock","Follow up gracefully without pushy job-begging"]'::jsonb, 'Beginner', 3, 'published'),
    ('724b3805-0350-ec5d-37b2-c7c5811e14c5', 'authentic-networking-relationship-building', 4, 'Module 4: Maintaining & Deepening Your Network', 'Keep promising connections alive sustainably across busy years with zero spammy newsletters.', '["Maintain a lightweight simple personal CRM habit","Craft genuine 2-minute seasonal \"thinking-of-you\" touchpoints"]'::jsonb, 'Beginner', 3, 'published'),
    ('25532378-8eb6-7d40-3d98-7fcc63d502b2', 'authentic-networking-relationship-building', 5, 'Module 5: Digital Presence & Community Contribution', 'Make networking effortless by sharing useful learning openly and participating thoughtfully in niche hubs.', '["Contribute high-signal comments and \"learning-in-public\" notes safely","Evaluate industry communities vs. noisy social feeds wisely"]'::jsonb, 'Intermediate', 3, 'published'),
    ('b9bb55fa-86bf-ba2f-79b2-f67bfa169f38', 'authentic-networking-relationship-building', 6, 'Module 6: Sustainable Networking Playbook Capstone', 'Integrate outreach craft, coffee-chat discipline, relationship tracking, and generous service into daily rhythm.', '["Design a realistic 30-minute weekly relationship habit fitting busy schedules","Navigate career transitions gracefully via long-built trust"]'::jsonb, 'Intermediate', 3, 'published'),
    ('8a63dd2c-74b8-881f-8e97-2becaa605b22', 'general-writing-foundations', 1, 'Module 1: Sentence Architecture & Active Meaning', 'Put concrete actors and strong verbs in charge of every sentence so meaning never stalls.', '["Prefer concrete subjects over abstract nominalizations","Eliminate weak verb-noun bloat cleanly"]'::jsonb, 'Beginner', 3, 'published'),
    ('f8129e59-e472-48ac-6da2-34ada49d713b', 'general-writing-foundations', 2, 'Module 2: Paragraph Unity & Logical Flow', 'Shape each paragraph into a cohesive unit guided by one topic claim and smooth transitions.', '["Draft unified topic sentences","Link paragraphs with explicit known-to-new chaining"]'::jsonb, 'Beginner', 3, 'published'),
    ('7ae76796-1287-dfbc-b050-2c448eab42f0', 'general-writing-foundations', 3, 'Module 3: Word Choice, Tone & Precision', 'Choose exact words, remove empty intensifiers, and tune register to your reader.', '["Replace vague modifiers with measurable facts","Calibrate formal, neutral, and conversational registers"]'::jsonb, 'Beginner', 3, 'published'),
    ('61397307-5081-5dd3-816c-7c60cd61fe05', 'general-writing-foundations', 4, 'Module 4: Planning, Outlining & Drafting Workflows', 'Separate chaotic idea generation from structured drafting so blank pages stop stalling progress.', '["Build functional section outlines before drafting","Apply rapid messy first drafts to beat writer’s block"]'::jsonb, 'Beginner', 3, 'published'),
    ('60a3ad1e-5d57-212f-c399-35fea2ff3c1a', 'general-writing-foundations', 5, 'Module 5: Revision Passes & Structural Editing', 'Edit in disciplined top-down layers—structure first, sentences second, mechanics last.', '["Run a 3-pass macro-to-micro edit workflow","Test drafts via reverse outlining and read-aloud checks"]'::jsonb, 'Intermediate', 3, 'published'),
    ('ece2d6a0-ad80-8dba-5055-c4efb80cfb84', 'general-writing-foundations', 6, 'Module 6: Everyday Formats & Practical Polishing', 'Adapt core writing craft cleanly across explanatory articles, guides, and reflections.', '["Write effective openings and crisp conclusions","Format multi-section texts for modern screen reading"]'::jsonb, 'Intermediate', 3, 'published'),
    ('25ee7290-7640-3aa7-3ae7-6687ed69b96c', 'professional-writing-essentials', 1, 'Module 1: Purpose-Driven Workplace Documents', 'Match internal and external documents cleanly to reader constraints and desired actions.', '["Distinguish informational briefs, decision memos, and SOPs","Front-load purpose and required sign-off cleanly"]'::jsonb, 'Beginner', 3, 'published'),
    ('2faa1303-c068-db2c-9a15-5e6883feb862', 'professional-writing-essentials', 2, 'Module 2: Proposals & Persuasive Workplace Cases', 'Structure internal initiatives and client proposals around shared value, realistic scope, and clear trade-offs.', '["Connect proposed solutions directly to stakeholder pain","Define crisp in-scope vs. out-of-scope boundaries"]'::jsonb, 'Beginner', 3, 'published'),
    ('1a64a709-e521-9d66-54f9-0943b568ff6a', 'professional-writing-essentials', 3, 'Module 3: Standard Operating Procedures (SOPs) & Guides', 'Document repeatable processes cleanly so new teammates execute accurately without shadowing calls.', '["Format task procedures with prerequisites, checks, and edge cases","Separate conceptual context from step-by-step commands"]'::jsonb, 'Beginner', 3, 'published'),
    ('1234f49a-912a-43f7-149c-e42500e57db8', 'professional-writing-essentials', 4, 'Module 4: Client Updates, Meeting Recaps & Reporting', 'Run transparent external communication cadences that minimize anxiety and lock in clear accountability.', '["Write crisp client status digests in 5 minutes","Capture action-led meeting notes that drive follow-through"]'::jsonb, 'Beginner', 3, 'published'),
    ('a4f503f0-4502-3709-ea4a-7fa93054b7e4', 'professional-writing-essentials', 5, 'Module 5: Navigating Sensitive & Escalated Written Moments', 'Deliver difficult news, decline out-of-scope requests, and respond cleanly when tensions run hot.', '["Reframe \"no\" into constructive bounded options","Handle missed deadlines or mistakes with high accountability"]'::jsonb, 'Intermediate', 3, 'published'),
    ('002374b4-41a1-c398-cb11-8ed206140614', 'professional-writing-essentials', 6, 'Module 6: Tone Consistency & Cross-Role Polish', 'Maintain reliable written craft across Slack/Teams, formal external docs, and executive briefs.', '["Adjust document polish and formality across roles","Apply a quick pre-send professional checklist reliably"]'::jsonb, 'Intermediate', 3, 'published'),
    ('e0271398-1b5e-cf8e-2947-d8b093866e93', 'business-writing-bluf-mastery', 1, 'Module 1: Bottom Line Up Front (BLUF)', 'Reverse traditional chronological storytelling so senior decision-makers absorb conclusions in five seconds.', '["Construct crisp BLUF lead blocks under 60 words","Distinguish BLUF business logic from academic narrative"]'::jsonb, 'Beginner', 3, 'published'),
    ('e766919e-a279-7921-29eb-015213521184', 'business-writing-bluf-mastery', 2, 'Module 2: Pyramid Principle & MECE Structuring', 'Organize complex business reasoning vertically and horizontally so no logic gap or overlap hides.', '["Build top-down logical pyramids linking summary to proof","Ensure argument pillars remain Mutually Exclusive, Collectively Exhaustive (MECE)"]'::jsonb, 'Beginner', 3, 'published'),
    ('16c1c799-ee25-a536-1901-b04fee770e6a', 'business-writing-bluf-mastery', 3, 'Module 3: Writing About Numbers & Financial Cases', 'Present budgets, forecasts, KPIs, and variance commentary transparently so business numbers tell an honest story.', '["Write insight headlines atop charts and financial tables","Explain budget variance cleanly using volume vs. rate logic"]'::jsonb, 'Beginner', 3, 'published'),
    ('b1f04c2d-1b38-39ae-9317-5a680dde54fa', 'business-writing-bluf-mastery', 4, 'Module 4: Executive Summaries & Stakeholder Briefs', 'Synthesize deep operational reports, market scans, or technical audits into standalone 1-page briefs.', '["Compress 10-page findings into a complete 1-page executive summary","Differentiate a summary from a vague table-of-contents teaser"]'::jsonb, 'Beginner', 3, 'published'),
    ('d4dee983-5554-27e1-9859-12d2bc9aa6f0', 'business-writing-bluf-mastery', 5, 'Module 5: Business Emails, Pitches & External Notes', 'Write external outreach, partnership pitches, contract follow-ups, and executive emails that earn prompt replies.', '["Craft high-reply subject lines and skimmable requests","Follow up persistently without sounding pushy or robotic"]'::jsonb, 'Intermediate', 3, 'published'),
    ('8c1ab3a5-e384-4aab-dfdb-b623cdf75c22', 'business-writing-bluf-mastery', 6, 'Module 6: Business Case Polish & Presentation', 'Ensure executive decks, prose memos, and numerical appendices align seamlessly without internal contradictions.', '["Eliminate cross-section metric mismatches cleanly","Review drafts through a skeptical executive lens"]'::jsonb, 'Intermediate', 3, 'published'),
    ('a8602a79-407a-8393-c8b8-da1fc498c574', 'creative-writing-foundations', 1, 'Module 1: Showing Scenes vs. Pure Summary', 'Anchor readers inside sensory physical moments instead of distant emotional reporting.', '["Distinguish scene dramatization from narrative summary","Use specific concrete details to evoke mood cleanly"]'::jsonb, 'Beginner', 3, 'published'),
    ('2cee3435-3fd3-cfad-f2ab-e3cb32b3839f', 'creative-writing-foundations', 2, 'Module 2: Character Desire, Flaw & Pressure', 'Build characters who drive plot through difficult choices rather than passively reacting to events.', '["Pair tangible external goals with internal character tension","Reveal character traits through consequential decisions"]'::jsonb, 'Beginner', 3, 'published'),
    ('9b163f74-b560-3bb7-ad01-16a324dbc122', 'creative-writing-foundations', 3, 'Module 3: Scene Structure & Narrative Pacing', 'Shape individual scenes as mini-stories containing goal, conflict, turn, and aftermath.', '["Structure scenes around Goal-Conflict-Outcome beats","Control pacing speed via scene length and white space"]'::jsonb, 'Beginner', 3, 'published'),
    ('bf1bdae5-83be-ee19-0527-b2467b3434d7', 'creative-writing-foundations', 4, 'Module 4: Dialogue, Subtext & Voice', 'Write crisp spoken exchanges where characters reveal attitude through deflection, rhythm, and what stays unsaid.', '["Use subtext instead of on-the-nose exposition","Format tags and action beats naturally"]'::jsonb, 'Beginner', 3, 'published'),
    ('612d21ca-312a-547c-a7e6-08273f6d80c6', 'creative-writing-foundations', 5, 'Module 5: Openings, Hooks & Narrative Arcs', 'Design satisfying narrative geometry from early inciting disruption through escalating complications and earned endings.', '["Craft openings balancing voice, world, and immediate question","Resolve central arcs smoothly without rushed coincidence"]'::jsonb, 'Intermediate', 3, 'published'),
    ('e8daafd7-04a1-f5e3-8f70-1bf6c6844a4f', 'creative-writing-foundations', 6, 'Module 6: Revising Fiction Like a Story Editor', 'Step back from raw drafts to cut slow openings, tighten prose rhythm, and elevate emotional precision.', '["Diagnose slow starts and flat scene middles","Tighten prose without stripping distinctive voice"]'::jsonb, 'Intermediate', 3, 'published'),
    ('46ed2eaa-7ed9-9476-837f-773f22f60232', 'storytelling-narrative-craft', 1, 'Module 1: Why Human Brains Remember Stories', 'Contrast dry information lists against tension-driven narrative structures that lock into memory.', '["Separate pure chronology (\"and then\") from causal narrative (\"but / therefore\")","Spot core stakes inside everyday accounts"]'::jsonb, 'Beginner', 3, 'published'),
    ('9c04e814-0739-f6a5-0608-9c8a4119f2c3', 'storytelling-narrative-craft', 2, 'Module 2: Classic Narrative Arcs in Applied Contexts', 'Structure inspiring, cautionary, and case-study stories cleanly without meandering.', '["Use the 5-Beat Applied Story Arc cleanly","Adapt story shapes to pitches, case studies, and keynotes"]'::jsonb, 'Beginner', 3, 'published'),
    ('c66aeeaa-f605-549f-a16d-1288750a3050', 'storytelling-narrative-craft', 3, 'Module 3: Vivid Detail, Contrast & Data Blending', 'Pair memorable sensory anchors with hard evidence so numbers carry genuine feeling.', '["Anchor key turns in concrete visual snapshots","Humanize cold statistics using story framing"]'::jsonb, 'Beginner', 3, 'published'),
    ('d6ec88ea-48ff-cfb3-382b-0cd40fe38206', 'storytelling-narrative-craft', 4, 'Module 4: Story Formats Across Channels', 'Stretch or compress the exact same core narrative cleanly for 30-second intros, blog articles, and live talks.', '["Run the Accordion Principle across lengths","Craft crisp micro-stories under 120 words"]'::jsonb, 'Beginner', 3, 'published'),
    ('2a261675-7f3d-7d6b-a874-692500b11561', 'storytelling-narrative-craft', 5, 'Module 5: Ethical Storytelling & Voice Honesty', 'Tell true personal, customer, and community stories respectfully without exaggeration, exploitation, or stolen credit.', '["Verify consent, accuracy, and fair credit cleanly","Avoid fabricated drama or savior framing"]'::jsonb, 'Intermediate', 3, 'published'),
    ('53b0fa40-d41a-310e-59bb-066a8d4dbc2b', 'storytelling-narrative-craft', 6, 'Module 6: Performance, Revision & Story Libraries', 'Rehearse pacing, silence, and physical delivery cleanly and curate a reusable personal bank of tested stories.', '["Use pacing, eye contact, and vocal shifts on turns","Maintain a searchable indexed bank of real workplace stories"]'::jsonb, 'Intermediate', 3, 'published'),
    ('ccf2c135-b0dc-2090-60f1-d3c7dc694e9e', 'copywriting-conversion-craft', 1, 'Module 1: Voice of Customer & Outcome Psychology', 'Mine real buyer frustrations and mirror exact customer words instead of guessing clever slogans in a vacuum.', '["Translate internal specs into customer Outcomes via the \"So What?\" test","Extract vivid copy hooks from customer reviews and support threads"]'::jsonb, 'Intermediate', 3, 'published'),
    ('ad94a869-e7bc-255b-dc53-bb6906a356c2', 'copywriting-conversion-craft', 2, 'Module 2: Headlines, Hooks & Subheads', 'Craft compelling headlines and scannable subheadings that stop scroll and pull readers smoothly down the page.', '["Use proven high-clarity headline formulas cleanly","Write subhead chains that tell the complete pitch on scan"]'::jsonb, 'Intermediate', 3, 'published'),
    ('2995cb08-9ced-6f05-fb86-24e79fcb4a63', 'copywriting-conversion-craft', 3, 'Module 3: Classic Persuasive Frameworks (PAS & AIDA)', 'Structure complete landing pages, ads, and sales emails systematically without inventing sequence from scratch.', '["Apply Problem-Agitate-Solution (PAS) empathetically","Map AIDA across multi-section conversion pages"]'::jsonb, 'Intermediate', 3, 'published'),
    ('7e375faa-fa0c-8566-aa8d-ec0c46d95cc6', 'copywriting-conversion-craft', 4, 'Module 4: Proof, Objection Handling & Microcopy', 'Convert cautious readers by addressing silent hesitations transparently and refining high-impact UI button/form copy.', '["Upgrade vague praise quotes into outcome proof","Optimize button microcopy, form labels, and pricing FAQs"]'::jsonb, 'Intermediate', 3, 'published'),
    ('fc25ead6-04ca-a7d0-d8cc-1abffc13e288', 'copywriting-conversion-craft', 5, 'Module 5: Email, Ad & Multi-Channel Copywriting', 'Adapt persuasion sharply to tight character limits, subject-line curiosity, and email lifecycle flows.', '["Hook fast within cramped social and search ad slots","Structure clean 3-email welcome and nurture sequences"]'::jsonb, 'Intermediate', 3, 'published'),
    ('26c7c179-eeee-6b63-f7a7-75855638222c', 'copywriting-conversion-craft', 6, 'Module 6: Ethical Conversion, Testing & Copy Audits', 'Replace dark-pattern pressure with trustworthy urgency and measure copy performance cleanly via structured tests.', '["Contrast genuine urgency against manipulative fake countdowns","Formulate testable copy hypotheses before running split tests"]'::jsonb, 'Intermediate', 3, 'published'),
    ('191567f5-4ac3-1101-b5e4-f62856e45805', 'technical-writing-documentation', 1, 'Module 1: Information Architecture & Diataxis', 'Organize documentation deliberately so learners seeking hands-on tutorials never trip over dry reference tables.', '["Classify docs into Tutorials, How-Tos, Explanations, and Reference cleanly","Diagnose mixed-mode documentation fatigue"]'::jsonb, 'Intermediate', 3, 'published'),
    ('fccdd898-ead5-a394-07f5-1325085c6c05', 'technical-writing-documentation', 2, 'Module 2: Writing Unambiguous Technical Procedures', 'Author task guides with exact UI anchors, active imperative voice, and clear expected terminal outputs.', '["Format imperative task steps avoiding compound multi-click traps","Show crisp expected results alongside commands"]'::jsonb, 'Intermediate', 3, 'published'),
    ('35caa7bf-7c78-e77c-9703-a503a6670ffa', 'technical-writing-documentation', 3, 'Module 3: API Reference & Developer Documentation', 'Document REST/JSON endpoints, request schemas, authentication patterns, and status codes clearly.', '["Structure uniform endpoint references with params, payloads, and responses","Provide working copy-paste curl/JS examples with realistic data"]'::jsonb, 'Intermediate', 3, 'published'),
    ('e7240d8a-1685-c26b-44e8-1bbe136bf590', 'technical-writing-documentation', 4, 'Module 4: Diagrams, Tables & Visual Clarity', 'Choose the cleanest representation—tables, flow diagrams, or callouts—when plain prose turns tangled.', '["Convert conditional prose mazes into clean decision tables","Write accessible alt-text and crisp technical diagrams"]'::jsonb, 'Intermediate', 3, 'published'),
    ('2d5c34de-2be8-ec85-d6e9-aa5f4dcc6bbd', 'technical-writing-documentation', 5, 'Module 5: Style Guides, Clarity & Release Docs', 'Craft crisp changelogs, deprecation notices, and docs adhering smoothly to Google or Microsoft style principles.', '["Write honest developer changelogs highlighting breaking impact first","Eliminate weak future-tense clutter (\"will display\") in technical specs"]'::jsonb, 'Intermediate', 3, 'published'),
    ('28535f22-56ee-6c60-4239-326b33bdb121', 'technical-writing-documentation', 6, 'Module 6: Docs-as-Code, Review & Maintenance', 'Treat documentation cleanly inside code workflows, test freshness regularly, and build low-drift knowledge habits.', '["Apply Docs-as-Code review alongside PR code changes","Measure documentation usefulness via support deflection and feedback loops"]'::jsonb, 'Intermediate', 3, 'published'),
    ('7ddfeb80-4448-5be6-3d34-5c93fa32c903', 'academic-writing-evidence-synthesis', 1, 'Module 1: Arguable Theses & Research Questions', 'Move beyond obvious descriptive topics to craft narrow, contestable academic claims backed by evidence.', '["Convert broad factual topics into genuine analytical theses","Balance nuance and specificity inside opening abstracts"]'::jsonb, 'Intermediate', 3, 'published'),
    ('3033afad-ea18-1cec-18e1-70bb467ac862', 'academic-writing-evidence-synthesis', 2, 'Module 2: Synthesis Matrix & Literature Integration', 'Weave sources together in dialogue around themes rather than stacking disconnected one-paragraph summaries.', '["Organize sources into thematic synthesis matrices","Put authors in active conversation (\"Whereas Smith argues..., Lee demonstrates...\")"]'::jsonb, 'Intermediate', 3, 'published'),
    ('ddc13f12-57ea-69c9-61f5-097c0acbec79', 'academic-writing-evidence-synthesis', 3, 'Module 3: Paragraph Logic & Scholarly Hedge Tone', 'Build rigorous analytical paragraphs using MEAL/TEEL structure and calibrate certainty without passive bloat or exaggeration.', '["Construct complete MEAL paragraphs with explicit evidence linkage","Use scholarly hedging (\"suggests\", \"indicates within\") accurately"]'::jsonb, 'Intermediate', 3, 'published'),
    ('a2af6737-91e6-c30b-023b-6ef02a1a2c1e', 'academic-writing-evidence-synthesis', 4, 'Module 4: Academic Integrity, Paraphrasing & Attribution', 'Distinguish genuine paraphrasing from mosaic patchwriting cleanly and manage APA/MLA/Chicago conventions accurately.', '["Paraphrase ideas through deep comprehension instead of word-swapping","Apply consistent in-text and reference attribution rules"]'::jsonb, 'Intermediate', 3, 'published'),
    ('64017f13-cce2-cede-44cc-8b67fada48a4', 'academic-writing-evidence-synthesis', 5, 'Module 5: Addressing Limitations, Counterarguments & Methods', 'Strengthen academic persuasiveness by openly addressing counter-evidence and clarifying research bounds transparently.', '["Steelman and refute or integrate credible counterarguments","Write clear scope limitations without undermining thesis value"]'::jsonb, 'Intermediate', 3, 'published'),
