-- 9. Practical Module Activities (386)
insert into public.activities (id, phase_id, lesson_id, position, title, description, instructions, expected_output, est_minutes, is_required, resources)
values
  ('16685950-0db0-224b-fdfd-358686131332'::uuid, '1452f148-671a-6af7-3d7d-91427b39afa1'::uuid, null::uuid, 1, 'Inspect and Map a Live Webpage Architecture', 'Open any public homepage in DevTools Elements and Network tabs. Document its landmark tags, stylesheet count, and largest layout shift culprit.', 'Inspect a site in DevTools (F12), identify <header>, <nav>, <main>, <footer>, and note 3 CSS custom properties or font rules.', 'A brief 5-line structural breakdown saved in your activity notes.', 25, true, '[]'::jsonb),
  ('846f7c5c-f69f-c0b2-25a3-a57a0eb82b82'::uuid, 'd038cf02-89ce-4d92-fa33-4a10e271793e'::uuid, null::uuid, 1, 'Write a Semantic 3-Section Business Homepage Skeleton', 'Draft pure HTML5 (no CSS yet) for a local service business with <header>, <nav>, hero <section>, services <article> cards, and <footer>.', 'Verify there is exactly one <h1>, no skipped heading levels, and meaningful alt text on every <img>.', 'Valid semantic HTML document outline verified without skipped heading levels.', 30, true, '[]'::jsonb),
  ('361b7cd4-98ef-f968-ea06-2667ec01e775'::uuid, '2d272456-d4a8-88d6-a92e-1eb58dcc0503'::uuid, null::uuid, 1, 'Build a Reusable Tokenised Stylesheet', 'Define :root variables for background, surface, primary text, accent colour, and spacing scale, then style a 2-card section using clean class selectors.', 'Verify WCAG AA contrast (>= 4.5:1) on body text and buttons.', 'CSS file using :root tokens and border-box sizing with zero !important overrides.', 30, true, '[]'::jsonb),
  ('d73a12fb-d9c0-bde0-3391-2aa3557d7ea7'::uuid, '1939f24b-98de-af0a-4beb-3217cfcdacba'::uuid, null::uuid, 1, 'Implement a Responsive Header + 3-Column Feature Grid', 'Create a responsive page layout that stacks cleanly at 375px, switches to 2 columns at 768px, and shows 3 equal-height cards at 1200px.', 'Test both 375px and 1440px viewports in DevTools and confirm zero horizontal scroll.', 'Flexbox navigation bar and CSS Grid card grid with zero overflow.', 35, true, '[]'::jsonb),
  ('8508b5d0-f72d-1092-28f8-750b845597ab'::uuid, '420b4329-9c17-0c00-c0fd-c951a1cc859a'::uuid, null::uuid, 1, 'Write a Service Catalogue Filter & Price Calculator', 'Given an array of 6 service packages, write pure JS functions to filter by category, format prices, and compute total selected quote cost.', 'Use const, .filter(), .map(), and .reduce() without mutating the source array.', 'Three pure JS helper functions tested with sample objects.', 30, true, '[]'::jsonb),
  ('1a7f5c3b-ff21-c5a5-c852-123ab635cfee'::uuid, 'b5b3aedb-70a3-ad9b-f3cc-53d5e98b49e8'::uuid, null::uuid, 1, 'Build an Interactive FAQ Accordion & Category Filter', 'Wire vanilla JS click handlers that toggle aria-expanded on FAQ items and filter visible service cards dynamically.', 'Update both the visual state and aria-expanded attribute when toggling an accordion row.', 'Interactive FAQ accordion and category filter working with keyboard and mouse.', 30, true, '[]'::jsonb),
  ('531a06e5-0128-b999-b11e-1dfcf550a45d'::uuid, 'fd887f97-0b99-8407-d9b7-28bc23d4f741'::uuid, null::uuid, 1, 'Create a Validated Business Inquiry Form', 'Build a contact/quote form checking name length, valid email format, service selection, and 20+ character message with inline field errors.', 'Prevent default submission on invalid input, focus the first invalid field, and show a confirmation banner on success.', 'Accessible contact form with inline errors and live submission confirmation.', 30, true, '[]'::jsonb),
  ('67630f50-f116-a2d4-68a0-dd402f9e6969'::uuid, 'd4e2b59d-c916-e976-6b79-4d636f308e48'::uuid, null::uuid, 1, 'Run a Complete Pre-Launch Lighthouse & Keyboard Audit', 'Test your multi-section business website using keyboard Tab navigation, mobile emulation, and DevTools Lighthouse prior to deployment.', 'Record your scores and list 2 concrete improvements made before final publish.', 'Verified keyboard focus flow, compressed images, and clean deployment URL.', 30, true, '[]'::jsonb),
  ('e782926d-f5e6-3387-6196-0cb09bf218a5'::uuid, '31078ffa-e680-0e73-5784-4bc0204f658f'::uuid, null::uuid, 1, 'Visual Brief Audit & Tear-Sheet Critique', 'Select one printed flyer or event poster you encounter this week and identify its primary message, secondary callout, and target audience.', 'Write 3 bullets: what grabs attention first, what action is requested, and one visual improvement.', 'Structured 3-point design critique saved in notes.', 25, true, '[]'::jsonb),
  ('a2415faa-746f-0294-0cfa-a84184989717'::uuid, '5cb69c74-cde2-63c7-9eff-99d475b442fe'::uuid, null::uuid, 1, 'Negative Space & Scale Contrast Study', 'Draft two versions of an event announcement card: one cluttered, and one refined using generous whitespace and a 3:1 headline-to-body scale ratio.', 'Leave at least 30% open negative space around your primary focal area.', 'Short comparison note describing how whitespace changed readability.', 30, true, '[]'::jsonb),
  ('35cd1db0-f22f-4e53-1033-b1ac60f2e9b8'::uuid, '72747bc7-f08d-7150-456f-63ed8621c540'::uuid, null::uuid, 1, 'Curate a 3-Swatch 60-30-10 Palette with Contrast Check', 'Select one dominant neutral background (60%), one structural surface/text tone (30%), and one focal accent (10%), verifying >= 4.5:1 text contrast.', 'Record hex values plus planned CMYK print adjustments.', '3-swatch palette table with verified foreground/background contrast ratios.', 25, true, '[]'::jsonb),
  ('c34f47f8-d545-bc0d-309a-ba7966465546'::uuid, 'a536bd2d-4629-4ffd-e289-1fb96a3701db'::uuid, null::uuid, 1, 'Design a 3-Level Typographic Specimen Sheet', 'Combine one expressive Display heading typeface with a neutral readable Body font across H1, Subhead, Body, and Metadata sizes.', 'Keep line lengths between 45–75 characters and avoid centred multi-line body paragraphs.', 'Documented font pairing with exact sizes, weights, and line heights.', 30, true, '[]'::jsonb),
  ('975098ec-fc0e-a52e-2b15-bffc2aee3760'::uuid, '649489f2-ad65-af24-188f-a3aa20b13aa2'::uuid, null::uuid, 1, 'Rebuild a Cluttered Flyer Onto a 6-Column Grid', 'Plan a 6-column or 12-column grid with uniform outer margins and align every headline, image edge, and venue detail block onto grid lines.', 'Verify zero stray floating elements sit off-grid without intentional reason.', 'Grid specification and alignment notes.', 30, true, '[]'::jsonb),
  ('fe9f726b-ee83-f2f1-4fc4-27fe71faf1c9'::uuid, '01eaf2c3-097d-3b9f-0c1d-97df91122f34'::uuid, null::uuid, 1, 'Author a 1-Page Fictional Business Brand Sheet', 'Invent a fictional business (bakery, bike repair studio, bookstore, or design workshop) with name, tagline, 3 tone adjectives, 2 fonts, and 3 colours.', 'Use this exact fictional business later for your final promotional flyer project.', 'Brand sheet outlining audience, tone, fonts, and hex/CMYK palette.', 30, true, '[]'::jsonb),
  ('584669c9-e628-f194-5023-3a2c8d87e5db'::uuid, 'd1af902a-0525-a077-325b-48ae16152342'::uuid, null::uuid, 1, 'Build a Layered Digital Template in Figma, Canva, or Affinity', 'Set up an A5 or Letter flyer artboard with 3mm bleed guides, named layer groups (Background, Visual, Copy, Footer), and reusable colour/text styles.', 'Verify all text uses shared styles and photos sit inside clean masked frames.', 'Confirmation of structured layer hierarchy and bleed setup.', 30, true, '[]'::jsonb),
  ('e5133ac1-c0e6-4dc1-f713-9f316d5e5273'::uuid, '70274843-cdb0-65d3-eec9-1e9773769b27'::uuid, null::uuid, 1, 'Pre-Press Flight Check & Export Verification', 'Inspect your finished promotional flyer at 100% zoom for spelling, alignment, 3mm bleed extension, and clean PDF/PNG export.', 'Check spelling of all dates/addresses twice and confirm zero clipped edge text.', 'Verified print-ready PDF and crisp PNG export ready for capstone submission.', 25, true, '[]'::jsonb),
  ('c2b6d708-492c-a268-158e-ab2b848299ff'::uuid, '6ee2ae2b-51e5-30da-6985-df81dcd26c65'::uuid, null::uuid, 1, 'Map a Full-Funnel Channel Matrix', 'Pick a real or fictional product and document one Owned, one Earned, and one Paid touchpoint supporting each funnel stage.', 'Identify the primary conversion event (lead form, booking, or checkout) before choosing channels.', '4-stage funnel table mapping channel + goal + CTA.', 25, true, '[]'::jsonb),
  ('55761b8f-b1fc-3202-c73a-80266cc85349'::uuid, '4fbbb134-2d0a-2a8f-0cd3-2e5d2da2f1ac'::uuid, null::uuid, 1, 'Voice-of-Customer Pain & Objection Sheet', 'Read 10 real public customer reviews in your target niche and extract 5 exact phrases describing frustrations, desired outcomes, and doubts.', 'Record verbatim customer wording rather than marketing buzzwords.', '5 verbatim customer pain/desire insights ready for copywriting.', 30, true, '[]'::jsonb),
  ('d8799a0c-df58-7093-ec77-bfe649c455e0'::uuid, 'eef6d687-2e34-9aa3-e674-dc02fe223505'::uuid, null::uuid, 1, 'Design a 3-Pillar Content Matrix & 1-to-4 Repurposing Plan', 'Define 3 educational content pillars for your campaign brand and outline how one flagship article turns into 4 platform-native posts.', 'Include headline, target takeaway, and soft CTA for each asset.', 'Content pillar plan with 4 derivative formats.', 25, true, '[]'::jsonb),
  ('195eb8ed-d92b-6d6f-060c-870e5605778a'::uuid, '8927aa09-f63d-ace2-96c4-a60f0deee13b'::uuid, null::uuid, 1, 'Draft 4 Platform-Native Social Posts for One Offer', 'Write hooks, body text, visual direction, and engagement prompts for 4 posts tailored to 2 chosen channels.', 'Make sure the opening line earns attention without clickbait.', '4 formatted social post drafts with visual briefs.', 30, true, '[]'::jsonb),
