  ('7058d5c4-2058-c69d-e632-3b12dba770f3'::uuid, 'b50845a3-6377-ff57-65b2-914d48ec9330'::uuid, 1, 'multiple_choice', 'medium', 1, 'Which rewrite best eliminates nominalization clutter?', '', '["Management performed an assessment of remote tooling.","Management assessed remote tooling this week.","An assessment was carried out regarding tooling."]'::jsonb, 1, '{}'::jsonb, 'Direct actor ("Management") + strong verb ("assessed") removes empty helper words.'),
  ('301e47d8-f223-b29f-e321-b69b6ecbba9c'::uuid, 'b50845a3-6377-ff57-65b2-914d48ec9330'::uuid, 2, 'scenario', 'medium', 1, 'What does the Known-to-New principle recommend?', '', '["Put unfamiliar metrics at the start of every sentence","Open with familiar context from the prior line and end with new information","Avoid all transition words"]'::jsonb, 1, '{}'::jsonb, 'Starting from familiar context bridges sentences smoothly into fresh claims.'),
