  ('abd3dd0f-3cf8-8223-0649-5361cbd7a6e8'::uuid, 'f8c11c83-c68d-de15-da50-e06476e54c7e'::uuid, 5, 'multiple_choice', 'hard', 1, 'How do you cure a stalled, perfectionist opening paragraph?', '', '["Spend four hours polishing line one","Bracket placeholders, draft middle sections first, and craft the hook last","Delete the outline"]'::jsonb, 1, '{}'::jsonb, 'Drafting middle proof first clarifies exactly what hook the opening needs.'),
  ('313acb63-c239-0c98-9cc2-dfc309bf99e8'::uuid, '4247ab54-6f88-2c3a-c1c0-771142f74b1f'::uuid, 1, 'multiple_choice', 'medium', 1, 'Where should the recommendation and budget impact sit inside a decision memo?', '', '["Buried in section four after full methodology","In the opening summary block right at the top","Inside a separate calendar invite"]'::jsonb, 1, '{}'::jsonb, 'Decision-makers scan the top block first to orient all subsequent evidence.'),
  ('d3792204-57a7-3a88-4013-db53306e2a85'::uuid, '4247ab54-6f88-2c3a-c1c0-771142f74b1f'::uuid, 2, 'scenario', 'medium', 1, 'How should an operational SOP write multi-step clicks cleanly?', '', '["As long narrative paragraphs","One numbered step per observable imperative action with verification checks","Without listing prerequisites"]'::jsonb, 1, '{}'::jsonb, 'Single-action imperative steps paired with verification states prevent execution slips.'),
  ('81635d7c-9a5f-4523-0277-d2a005c41fce'::uuid, '4247ab54-6f88-2c3a-c1c0-771142f74b1f'::uuid, 3, 'multiple_choice', 'medium', 1, 'Why include explicit Out of Scope bullets in client proposals?', '', '["To discourage future work","To set fair expectations upfront and prevent silent scope creep","To replace timelines"]'::jsonb, 1, '{}'::jsonb, 'Clear exclusions prevent misunderstandings later when priorities shift.'),
